content:         1→// The two files the server keeps outside the game folder (serve.mjs): settings.json and save.json. Only these two, only on
        2→// this machine. Every call here fails quietly: when the server can't be reached, the page plays on with this browser's copy.
        3→const NAMES = ['settings', 'save'];
        4→const url = (name) => `/api/${name}`;
        5→
        6→// { reached: true, data } (the server answers null when there is no file yet), or { reached: false }
        7→export async function getFile(name) {
        8→  if (!NAMES.includes(name) || typeof fetch !== 'function') return { reached: false };
        9→  try {
       10→    const r = await fetch(url(name), { cache: 'no-store', signal: AbortSignal.timeout(2500) });
       11→    if (!r.ok) return { reached: false };
       12→    return { reached: true, data: await r.json() };
       13→  } catch { return { reached: false }; }
       14→}
       15→
       16→// written a moment later, the last version only (a stepper pressed ten times sends one file); resolves true once stored
       17→const queue = {};
       18→export function putFile(name, data, delay = 300) {
       19→  if (!NAMES.includes(name) || typeof fetch !== 'function') return Promise.resolve(false);
       20→  const q = queue[name] || (queue[name] = { waiters: [], timer: null, busy: null });
       21→  q.body = JSON.stringify(data); clearTimeout(q.timer);
       22→  q.timer = setTimeout(() => send(name), delay);
       23→  return new Promise((res) => q.waiters.push(res));
       24→}
       25→async function send(name, keepalive = false) {
       26→  const q = queue[name]; clearTimeout(q.timer); q.timer = null;
       27→  if (q.busy) await q.busy;
       28→  const body = q.body, waiters = q.waiters.splice(0);
       29→  q.busy = (async () => {
       30→    let ok = false;
       31→    try { ok = (await fetch(url(name), { method: 'PUT', headers: { 'content-type': 'application/json' }, body, keepalive: keepalive && body.length < 60000 })).ok; } catch { /* unreachable */ }
       32→    waiters.forEach((w) => w(ok));
       33→  })();
       34→  await q.busy; q.busy = null;
       35→}
       36→// send what is waiting now (before a reload, or when the page is closed)
       37→export function flush(keepalive = false) {
       38→  return Promise.all(Object.keys(queue).map((n) => (queue[n].timer ? send(n, keepalive) : queue[n].busy)));
       39→}
       40→if (typeof addEventListener === 'function') addEventListener('pagehide', () => { flush(true); });
