       12→export const DEFAULTS = copy({
       13→  moves: MOVES, outfits: OUTFITS, hairs: HAIRS, shoes: SHOES, accs: ACCS, pieces: PIECES, snacks: SNACKS, upgrades: UPGRADES,
       14→  classes: Object.fromEntries(CLASSES.map((c) => [c.id, c])), numbers: NUMBERS, names: NAMES, start: { start: START },
