  1→// The grown-ups' settings screen. Behind a long press on ⚙️ and a sum typed in, so a child doesn't open it by accident.
  2→// Every field of settings.js, with its limits, a kind message when a value is refused, and ↺ back to the game's value.
  3→// Each change is stored at once (the server's settings.json, and a copy in this browser); closing reloads the game, which
  4→// lays the settings over the default rows before anything reads them (main.js).
  5→import { G, resetAll } from './state.js';
  6→import { t, nm } from './i18n.js';
  7→import { esc, toast } from './ui.js';
  8→import { MOVES, OUTFITS, STYLES, NUMBERS, START } from './data.js';
  9→import { SCHEMA, DEFAULTS, ICONS, THEMES, MAX_NEW, check, withField, valueOf, newRow, newIds, sanitize, fieldsOf, isNewId } from './settings.js';
 10→import { getFile, putFile, flush } from './store.js';
 11→
 12→const LOCAL_KEY = 'gala-settings-copy', APPLIED_KEY = 'gala-settings-applied', MAX_FILE = 100 * 1024;
 13→export const GS = { file: { v: 1, rows: {} }, reached: true, dirty: false, tab: 'moves', openRows: new Set(), msg: null, status: '' };
 14→const copy = (o) => JSON.parse(JSON.stringify(o));
 15→const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
 16→
 17→/* ---------------- start-up: where the settings come from ---------------- */
 18→// the server's file; this browser's copy only when the server can't be reached (or has lost its file)
 19→export async function loadSettings() {
 20→  const r = await getFile('settings');
 21→  let local = null; try { local = JSON.parse(localStorage.getItem(LOCAL_KEY) || 'null'); } catch { /* a broken copy */ }
 22→  GS.reached = r.reached;
 23→  GS.file = sanitize(r.reached && r.data ? r.data : local || {}).file;
 24→  if (r.reached && !r.data && local) putFile('settings', GS.file, 0);
 25→  keepCopy();
 26→  return GS.file;
 27→}
 28→const keepCopy = () => { try { localStorage.setItem(LOCAL_KEY, JSON.stringify(GS.file)); } catch { /* storage blocked */ } };
 29→// after the reload that applies them: say so
 30→export function sayApplied() { try { if (sessionStorage.getItem(APPLIED_KEY)) { sessionStorage.removeItem(APPLIED_KEY); toast(t().gs.applied); } } catch { /* storage blocked */ } }
 31→
 32→/* ---------------- the gate: a long press, then a sum ---------------- */
 33→export function bindGear(btn) {
 34→  let timer = null;
