 41→  btn.addEventListener('keydown', (e) => { if ((e.key === 'Enter' || e.key === ' ') && !e.repeat && !timer) start(e); });
 42→  btn.addEventListener('keyup', (e) => { if (e.key === 'Enter' || e.key === ' ') stop(true); });
 43→  btn.onclick = (e) => e.preventDefault();
