 48→  if (!gateEl) { gateEl = document.createElement('div'); gateEl.id = 'gate'; document.body.appendChild(gateEl); }
 49→  const ask = (msg = '') => {
 50→    const a = rnd(12, 19), b = rnd(3, 9), T = t().gs;
 51→    gateEl.innerHTML = `<div class="box" role="dialog" aria-modal="true" aria-labelledby="gateH"><h2 id="gateH">${esc(T.gateH)}</h2><p id="gateQ">${esc(T.gateQ(a, b))}</p>`
 52→      + `<input type="text" id="gateIn" inputmode="numeric" maxlength="4" autocomplete="off" aria-labelledby="gateQ"><p class="hint warn" id="gateMsg">${esc(msg)}</p>`
 53→      + `<div class="chips"><button type="button" class="big" id="gateOk">${esc(T.ok)}</button><button type="button" id="gateNo">${esc(T.cancel)}</button></div></div>`;
 54→    gateEl.hidden = false;
 55→    const inp = gateEl.querySelector('#gateIn'), shut = () => { gateEl.hidden = true; };
 56→    const go = () => { if (inp.value.trim() === String(a * b)) { shut(); openSettings(); } else ask(T.gateNo); };
 57→    gateEl.querySelector('#gateOk').onclick = go; gateEl.querySelector('#gateNo').onclick = shut;
 58→    inp.onkeydown = (e) => { if (e.key === 'Enter') go(); if (e.key === 'Escape') shut(); };
