content:         1→// The gala day as a pure function of the plan and the school: simulate() returns every verdict, every dancer's schedule,
        2→// the points and a trace of { t, who, step, verdict, say }. No DOM, no three.js, no words: the sheet turns `say` into
        3→// sentences. This is the engine the port would package; tests/engine.test.mjs runs it in Node.
        4→import {
        5→  RULES, CLS, NUMBERS, numDur, OTHER_ITEMS, itemKind, STYLES, MOVES, OUTFITS, HAIRS, SHOES, ACCS, PIECES, LOGE,
        6→  doorTiles, SNACKS, BACKDROP_THEMES, PARKING, seasonRules, hm,
        7→} from './data.js';
        8→
        9→export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
       10→export const rngFor = (seed) => { let a = seed >>> 0; return () => { a = (a + 0x6D2B79F5) >>> 0; let x = a; x = Math.imul(x ^ (x >>> 15), x | 1); x ^= x + Math.imul(x ^ (x >>> 7), x | 61); return ((x ^ (x >>> 14)) >>> 0) / 4294967296; }; };
       11→export const dancerId = (c, i) => `${c}-${i}`;
       12→const mean = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0);
       13→
       14→/* ---------------- what she owns ---------------- */
       15→// kind: 'outfit' | 'hair' | 'shoes' | 'acc' | 'piece' | 'snack' | 'up' (hall and car park) | 'food'
       16→const CATALOG = { outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS };
       17→export function isOwned(school, kind, id) {
       18→  if (kind === 'up') return !!school.upgrades[id];
       19→  const item = CATALOG[kind] ? CATALOG[kind][id] : null;
       20→  if (kind === 'food') return !!school.owned[`food:${id}`];
       21→  return !!item && (!item.price || !!school.owned[`${kind}:${id}`]);
       22→}
       23→export const stageOf = (school) => (school.upgrades.scene ? RULES.stageBig : RULES.stage);
       24→export const seatsOf = (school) => 112 + 14 * (school.upgrades.sieges || 0);
       25→
       26→/* ---------------- the dressing room ---------------- */
       27→export function footprint(f) { const p = PIECES[f.id]; return f.rot % 2 ? { w: p.d, d: p.w } : { w: p.w, d: p.d }; }
       28→// a piece that hangs on a wall must have its back against one: turning it changes which side is its back
       29→export function againstWall(f, cols) {
       30→  const fp = footprint(f);
       31→  switch (((f.rot % 4) + 4) % 4) {
       32→    case 0: return f.r === 0;
       33→    case 1: return f.c + fp.w === cols;
       34→    case 2: return f.r + fp.d === LOGE.rows;
       35→    default: return f.c === 0;
       36→  }
       37→}
       38→export function fits(f, list, cols, ignore) {
       39→  const fp = footprint(f);
       40→  if (f.c < 0 || f.r < 0 || f.c + fp.w > cols || f.r + fp.d > LOGE.rows) return false;
       41→  if (PIECES[f.id].flat) return true;
       42→  for (const [c, r] of doorTiles(cols)) if (c >= f.c && c < f.c + fp.w && r >= f.r && r < f.r + fp.d) return false;
       43→  for (const o of list) {
       44→    if (o === ignore || PIECES[o.id].flat) continue;
       45→    const q = footprint(o);
       46→    if (f.c < o.c + q.w && o.c < f.c + fp.w && f.r < o.r + q.d && o.r < f.r + fp.d) return false;
       47→  }
       48→  return true;
       49→}
       50→export function analyseLoge(school, totalDancers) {
       51→  const cols = school.logeCols, fx = { postes: 0, rail: 0, seats: 0, calm: 0, water: 0, fruit: 0, fan: 0, shoes: 0, screen: 0, sieste: 0, doudous: 0, barre: 0, clock: 0, music: 0 };
       52→  const invalid = []; let covered = 0;
       53→  for (const f of school.furniture) {
       54→    const p = PIECES[f.id]; if (!p) continue;
       55→    const fp = footprint(f); if (!p.flat) covered += fp.w * fp.d;
       56→    if (p.wall && !againstWall(f, cols)) { invalid.push(f); continue; }
       57→    for (const k of Object.keys(p.fx)) fx[k] += p.fx[k];
       58→  }
       59→  const tiles = cols * LOGE.rows;
       60→  return {
       61→    ...fx, postesRaw: fx.postes, postes: Math.max(1, fx.postes), calmRaw: fx.calm, calm: Math.min(30, fx.calm),
       62→    railCap: fx.rail * RULES.railCap, covered, tiles, clutter: covered / tiles > 0.5, invalid, totalDancers,
       63→    seatRatio: Math.min(1, fx.seats / Math.max(1, totalDancers)),
       64→  };
       65→}
       66→// minutes for a class to change from one number's costume to the next
       67→export function changeTime(prev, next, loge) {
       68→  const lines = [['outfit', OUTFITS[next.outfit].min, next.outfit]];
       69→  if (prev.shoes !== next.shoes) lines.push(['shoes', loge.shoes ? 1 : 2]);
       70→  if (prev.acc !== next.acc && next.acc !== 'aucun') lines.push(['acc', 1]);
       71→  if (loge.railCap < loge.totalDancers) lines.push(['rails', 3]);
       72→  if (loge.screen) lines.push(['screen', -1]);
       73→  if (loge.clutter) lines.push(['clutter', 2]);
       74→  const sum = lines.reduce((s, l) => s + l[1], 0);
       75→  return { min: Math.max(2, sum), sum, lines };
       76→}
       77→
       78→/* ---------------- a dance: the phrase, the spacing, the music ---------------- */
       79→// a dance: named blocks of steps, and the chain that says in which order the class dances them (a block can come back as
       80→// often as she likes, like a component placed many times). The engine reads the chain flat: one long run of steps, danced once.
       81→export function danceOf(np) {
       82→  const byId = Object.fromEntries(np.blocks.map((b) => [b.id, b])), moves = [], marks = [], times = {};
       83→  np.chain.forEach((bid, j) => { const b = byId[bid]; if (!b) return; marks.push({ j, block: bid, k0: moves.length, k1: moves.length + b.moves.length }); moves.push(...b.moves); times[bid] = (times[bid] || 0) + 1; });
       84→  return { A: np.A, B: np.B, costume: np.costume, moves, repeats: 1, marks, chainLen: marks.length, mostRepeated: Math.max(0, ...Object.values(times)), blocksUsed: Object.keys(times).length };
       85→}
       86→// cyclic: the last step leads back into the first (true for a block shown on its own, which may repeat; false for a whole dance)
       87→export function routineInfo(moves, style, cyclic = true) {
       88→  const M = moves.map((id) => MOVES[id]);
       89→  const phrase = M.reduce((s, m) => s + m.c, 0);
       90→  const links = (cyclic ? M : M.slice(0, -1)).map((m, k) => {
       91→    const n = M[(k + 1) % M.length], gap = Math.abs(m.b - n.a), off = n.st !== '*' && !n.st.split(' ').includes(style);
       92→    let score = gap === 0 ? 1 : gap === 1 ? 0.6 : 0; if (off) score *= 0.5;
       93→    return { k, from: moves[k], to: moves[(k + 1) % M.length], gap, off, score };
       94→  });
       95→  let dx = 0, dz = 0; const offsets = M.map((m) => { dx += m.dx || 0; dz += m.dz || 0; return { dx, dz }; });
       96→  const hardPairs = M.length > 1 ? links.filter((l) => MOVES[l.from].d >= 2 && MOVES[l.to].d >= 2).length : 0;
       97→  return {
       98→    phrase, links, avgHarmony: links.length ? mean(links.map((l) => l.score)) : 1, avgDiff: phrase ? M.reduce((s, m) => s + m.d * m.c, 0) / phrase : 0,
       99→    offsets, net: { dx, dz }, swaps: M.filter((m) => m.swap).length, distinct: new Set(moves.filter((id) => !MOVES[id].swap)).size,
      100→    hardPairs, starts: M.reduce((a, m, k) => (a.push(k ? a[k - 1] + M[k - 1].c : 0), a), []),
      101→  };
      102→}
      103→// where every dancer is after each move of each repetition; the spacing judged there
      104→export function judgeSpacing(np, cls, stage, info) {
      105→  const n = cls.n, A = np.A, B = info.swaps ? (np.B || np.A) : null, span = cls.span, out = { collide: [], hidden: [], offstage: [], bump: [], moved: 0 };
      106→  const statics = B ? [['A', A], ['B', B]] : [['A', A]];
      107→  for (const [tag, P] of statics) for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
      108→    const d = Math.hypot(P[i].x - P[j].x, P[i].z - P[j].z);
      109→    if (d < span - 1e-9) out.collide.push({ i, j, d, tag });
      110→    else if (Math.abs(P[i].x - P[j].x) < RULES.hideDx - 1e-9) out.hidden.push(P[i].z > P[j].z ? { b: i, f: j, tag, dx: Math.abs(P[i].x - P[j].x) } : { b: j, f: i, tag, dx: Math.abs(P[i].x - P[j].x) });
      111→  }
      112→  if (B) out.moved = Math.max(...A.map((p, i) => Math.hypot(p.x - B[i].x, p.z - B[i].z)));
      113→  const off = (p) => p.x > stage.halfW + 1e-9 || p.x < -stage.halfW - 1e-9 || p.z < -1e-9 || p.z > stage.depth + 1e-9;
      114→  const seenOff = new Set(), seenBump = new Set(), R = np.repeats, mv = np.moves;
      115→  let F = A, ox = 0, oz = 0;
      116→  const check = (P, r, k) => P.forEach((p, i) => { if (!seenOff.has(i) && off({ x: p.x + ox, z: p.z + oz })) { seenOff.add(i); out.offstage.push({ i, r, k, x: p.x + ox, z: p.z + oz, x0: p.x, z0: p.z }); } });
      117→  check(F, 0, -1);
      118→  for (let r = 0; r < R && r < 60; r++) for (let k = 0; k < mv.length; k++) {
      119→    const m = MOVES[mv[k]];
      120→    if (m.swap && B) {
      121→      const G = F === A ? B : A;
      122→      for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
      123→        if (seenBump.has(`${i}|${j}`)) continue;
      124→        for (let s = 1; s < 8; s++) {
      125→          const u = s / 8, xi = F[i].x + (G[i].x - F[i].x) * u, zi = F[i].z + (G[i].z - F[i].z) * u, xj = F[j].x + (G[j].x - F[j].x) * u, zj = F[j].z + (G[j].z - F[j].z) * u;
      126→          if (Math.hypot(xi - xj, zi - zj) < RULES.bump) { seenBump.add(`${i}|${j}`); out.bump.push({ i, j, r, k }); break; }
      127→        }
      128→      }
      129→      F = G;
      130→    }
      131→    ox += m.dx || 0; oz += m.dz || 0; check(F, r, k);
      132→  }
      133→  out.ok = !out.collide.length && !out.hidden.length && !out.offstage.length && !out.bump.length;
      134→  return out;
