      136→export function judgeMusic(id, d, info) {
      137→  const N = NUMBERS[id], have = info.phrase, diff = have - N.counts, endOf = (mk) => (mk.k1 > mk.k0 ? info.starts[mk.k1 - 1] + MOVES[d.moves[mk.k1 - 1]].c : info.starts[mk.k0] || 0);
