      139→  const over = diff > 0 ? d.marks.find((mk) => endOf(mk) > N.counts) : null;
      140→  return { counts: N.counts, bpm: N.bpm, dur: numDur(id), phrase: info.phrase, parts, have, diff, ok: diff === 0 && info.phrase > 0, stopsIn: over ? over.j + 1 : 0, playsOn: diff < 0 ? (-diff * 60) / N.bpm : 0 };
      141→}
