      143→/* ---------------- how the dancers feel at a moment of the evening ---------------- */
      144→// energy (tiredness), hunger, nerves (stage fright) and focus (brain fog), each 0..100
      145→export function classState(clsId, T, ctx) {
      146→  const c = CLS[clsId], { plan, loge } = ctx, snack = SNACKS[plan.snack] || SNACKS.rien, minutes = Math.max(0, (T - RULES.arrive) / 60);
