      158→  const thirst = loge.water ? 0 : Math.max(0, (T - hm(19, 30)) / 60) * 0.25;
      159→  const focus = clamp(100 - hunger * 0.6 - thirst - Math.max(0, 50 - energy) * 0.5, 5, 100);
      160→  return { energy: Math.round(energy), hunger: Math.round(hunger), nerves: Math.round(nerves), focus: Math.round(focus), thirst: Math.round(thirst), lines };
      161→}
      162→// a step's chance to go wrong, by how far it is above the class's level (round 2½: a fouetté for six-year-olds fails often)
      163→const GAP_P = { '-2': 0.0001, '-1': 0.0003, 0: 0.001, 1: 0.015, 2: 0.08 };
      164→// the chance that each dancer slips on each move, and forgets her steps on each repetition
      165→export function execution(cls, info, d, state) {
      166→  const exp = cls.exp, fat = 1 + (100 - state.energy) / 60, nerv = 1 + state.nerves / 120;
      167→  const sh = SHOES[d.costume.shoes], shoe = sh && sh.expMin && exp < sh.expMin ? 2.5 : 1, mv = d.moves;
      168→  const per = mv.map((id, k) => {
      169→    const m = MOVES[id], gap = clamp(m.d - exp, -2, 2), prev = k > 0 ? MOVES[mv[k - 1]] : null, streak = !!prev && m.d >= 2 && prev.d >= 2;
      170→    return { id, k, gap, streak, p: GAP_P[gap] * fat * nerv * shoe * (streak ? 1.5 : 1) };
      171→  });
      172→  const bored = Math.max(0, exp - 0.8 - info.avgDiff), long = Math.max(0, d.mostRepeated - 12);
      173→  const forget = (100 - state.focus) / 30000 + bored * 0.006 + long * 0.0004 * exp;
      174→  const expected = cls.n * (per.reduce((s, x) => s + x.p, 0) + d.chainLen * forget);
      175→  return { per, forget, bored, long, expected, fat, nerv, shoe };
      176→}
      177→const TARGET_DIFF = { 1: 1.2, 2: 1.8, 3: 2.4 };
      178→function wowOf(id, np, cls, info, spacing, plan, school, dance) {
      179→  const N = NUMBERS[id], c = np.costume, src = [];
      180→  if (info.distinct >= 5) src.push('variety');
      181→  if (dance.blocksUsed >= 3) src.push('structure');
      182→  if (Math.abs(info.avgDiff - TARGET_DIFF[cls.exp]) <= 0.4) src.push('level');
      183→  if ((OUTFITS[c.outfit].themes || []).includes(N.theme)) src.push('costume');
      184→  if ((ACCS[c.acc].themes || []).includes(N.theme)) src.push('acc');
      185→  if (info.swaps && spacing.moved >= 1) src.push('formation');
      186→  if ((BACKDROP_THEMES[plan.backdrop] || []).includes(N.theme)) src.push('backdrop');
      187→  if (school.upgrades.projecteurs) src.push('lights');
      188→  if (school.upgrades.boule && ['jazz', 'hiphop'].includes(N.style)) src.push('disco');
      189→  return { src, pts: Math.min(5, src.length) };
      190→}
