      192→/* ---------------- the evening's running order ---------------- */
      193→export function programme(plan, school, rules, loge) {
      194→  const active = new Set(rules.classes);
      195→  const hairTotal = rules.classes.reduce((s, c) => s + CLS[c].n * HAIRS[plan.hair[c] || 'queue'].min, 0);
      196→  const hairMin = Math.ceil(hairTotal / loge.postes), ready = RULES.hairStart + hairMin * 60;
      197→  const start = Math.max(plan.start, ready), startLate = start - plan.start;
      198→  let tt = start, prevDance = false, prevKind = null, floor = null, calmRun = 0;
      199→  const items = [], lastEnd = {}, lastNum = {}, yawns = [], swaps = [];
      200→  for (const id of plan.order) {
      201→    const kind = itemKind(id);
      202→    if (kind === 'number' && !active.has(NUMBERS[id].cls)) continue;
      203→    const isDance = kind === 'number' || kind === 'finale', co = isDance && prevDance ? RULES.setChange : 0;
      204→    let fl = 0;
      205→    if (rules.floors && kind === 'number') {
      206→      const need = STYLES[NUMBERS[id].style].floor;
      207→      if (floor && need !== floor) { fl = prevKind === 'interval' ? 0 : RULES.floorSwap; swaps.push({ id, to: need, free: fl === 0 }); }
      208→      floor = need;
      209→    }
      210→    tt += co + fl;
      211→    let s = tt, wait = 0, change = null;
      212→    if (kind === 'number') {
      213→      const cls = NUMBERS[id].cls;
      214→      if (lastEnd[cls] !== undefined) {
      215→        change = changeTime(plan.numbers[lastNum[cls]].costume, plan.numbers[id].costume, loge);
      216→        const readyC = lastEnd[cls] + change.min * 60; if (readyC > s) { wait = readyC - s; s += wait; }
      217→      }
      218→      if (rules.moods) { if (NUMBERS[id].mood === 'calme') { calmRun++; if (calmRun >= 2) yawns.push({ id, run: calmRun }); } else calmRun = 0; }
      219→    } else if (kind !== 'finale') calmRun = 0;
      220→    const dur = kind === 'interval' ? plan.interval : kind === 'number' ? numDur(id) : OTHER_ITEMS[id].dur;
      221→    items.push({ id, kind, start: s, end: s + dur, dur, co, fl, wait, change, floor: kind === 'number' ? floor : null });
      222→    tt = s + dur; prevDance = isDance; prevKind = kind;
      223→    if (kind === 'number') { lastEnd[NUMBERS[id].cls] = tt; lastNum[NUMBERS[id].cls] = id; }
      224→  }
      225→  const end = items[items.length - 1].end, late = Math.max(0, end - RULES.hallCloses);
      226→  const sleepy = lastEnd.petits !== undefined ? Math.max(0, lastEnd.petits - RULES.bedtime) : 0;
      227→  const waits = items.filter((i) => i.wait > 0);
      228→  return { items, lastEnd, lastNum, end, late, sleepy, waits, yawns, swaps, hairTotal, hairMin, ready, start, startLate, ok: !late && !sleepy && !waits.length && !startLate && !yawns.length };
      229→}
      230→
      231→/* ---------------- the goûter: classes reach the table in the order they leave the stage ---------------- */
      232→function judgeGouter(plan, rules, order) {
      233→  const finalEnd = order.items.find((i) => i.id === 'final').end;
      234→  const leave = (c) => (c === 'petits' ? order.lastEnd.petits + 120 : finalEnd + 120);
      235→  const sequence = [...rules.classes].sort((a, b) => leave(a) - leave(b) || order.lastEnd[a] - order.lastEnd[b]);
      236→  const offer = { cake: plan.cakeG * (RULES.cakeKcal / 100), crepes: (plan.crepes || 0) * RULES.crepeKcal, compotes: (plan.compotes || 0) * RULES.compoteKcal };
      237→  const kcal0 = offer.cake + offer.crepes + offer.compotes, cl0 = plan.bottles * RULES.bottleCl;
      238→  let kcal = kcal0, cl = cl0, cakeOut = null, juiceOut = null; const eaters = [];
      239→  for (const c of sequence) for (let i = 0; i < CLS[c].n; i++) {
      240→    const k = CLS[c].kcal, j = CLS[c].juice, gotK = kcal + 1e-9 >= k, gotJ = cl + 1e-9 >= j;
      241→    if (gotK) kcal -= k; else { if (!cakeOut) cakeOut = c; kcal = 0; }
      242→    if (gotJ) cl -= j; else { if (!juiceOut) juiceOut = c; cl = 0; }
      243→    eaters.push({ id: dancerId(c, i), cls: c, cake: gotK, juice: gotJ });
      244→  }
      245→  const needKcal = rules.classes.reduce((s, c) => s + CLS[c].n * CLS[c].kcal, 0), needCl = rules.classes.reduce((s, c) => s + CLS[c].n * CLS[c].juice, 0);
      246→  const variety = (plan.crepes > 0 ? 1 : 0) + (plan.compotes > 0 ? 1 : 0);
      247→  return { sequence, leave: Object.fromEntries(sequence.map((c) => [c, leave(c)])), eaters, cakeOut, juiceOut, offer, kcal0, cl0, needKcal, needCl, leftKcal: kcal0 - needKcal, leftCl: cl0 - needCl, variety, ok: !cakeOut && !juiceOut };
      248→}
