      250→/* ---------------- the car park (season 2 on) ---------------- */
      251→export function judgeParking(plan, school, rules, start) {
      252→  const P = PARKING, dancers = rules.classes.reduce((s, c) => s + CLS[c].n, 0);
      253→  const families = Math.round(dancers * P.perFamily), guests = P.guestsPerSeason * rules.season;
      254→  const famCars = school.upgrades.covoit ? Math.round(families * (1 - P.carpool)) : families, cars = famCars + guests;
      255→  const width = plan.parking.width, perRow = Math.floor(P.lotLength / width), rows = school.upgrades.rangee ? 2 : 1, bays = perRow * rows;
      256→  const W = plan.parking.doors * 60, rate = school.upgrades.placeur ? P.gateRatePlaceur : P.gateRate, gap = 60 / rate;
      257→  const walk = school.upgrades.navette ? P.shuttleWalk : P.overflowWalk, list = [];
      258→  let prev = -Infinity;
      259→  for (let k = 0; k < cars; k++) {
      260→    const arr = start - W + ((k + 0.5) * (W * 2 / 3)) / cars, through = Math.max(arr, prev + gap); prev = through;
      261→    const bay = k < bays ? k : null, seated = bay !== null ? through + (P.parkMin[width] + P.walkFromBay) * 60 : through + (P.overflowDrive + walk) * 60;
      262→    list.push({ k, arr, through, bay, seated, late: seated > start + 1e-6 });
      263→  }
      264→  const lateCars = list.filter((c) => c.late).length, queue = Math.max(0, ...list.map((c) => c.through - c.arr));
      265→  return {
      266→    dancers, families, famCars, guests, cars, width, perRow, rows, bays, doors: plan.parking.doors, rate, walk, list, lateCars,
      267→    lateParents: Math.round(lateCars * P.perCar), overflow: Math.max(0, cars - bays), queue, narrow: width < 2.5, ok: lateCars === 0,
      268→  };
      269→}
      270→
      271→/* ---------------- the whole day ---------------- */
      272→// input: { plan, school, season, mode: 'rehearsal' | 'try' | 'gala', seed }
      273→// the dice roll on gala night and in a try-out (each try its own seed); the general rehearsal only times the evening
      274→export function simulate({ plan, school, season = 1, mode = 'rehearsal', seed = 1 }) {
      275→  const rules = seasonRules(season), stage = stageOf(school), gala = mode === 'gala', rolls = gala || mode === 'try';
      276→  const totalDancers = rules.classes.reduce((s, c) => s + CLS[c].n, 0);
      277→  const loge = analyseLoge(school, totalDancers), order = programme(plan, school, rules, loge);
      278→  const rng = rngFor(seed), trace = [], seg = {};
      279→  const push = (t, who, step, verdict, say) => trace.push({ t, who, step, verdict, say });
      280→  const nums = order.items.filter((i) => i.kind === 'number'), finale = order.items.find((i) => i.id === 'final');
      281→
      282→  // every number: the spacing, the music, the harmony, how the dancers feel, what goes wrong
      283→  const perf = {}, costSoFar = {}, kOf = {};
      284→  for (const it of nums) {
      285→    const id = it.id, N = NUMBERS[id], cls = CLS[N.cls], np = plan.numbers[id], dance = danceOf(np), info = routineInfo(dance.moves, N.style, false);
      286→    const spacing = judgeSpacing(dance, cls, stage, info), music = judgeMusic(id, dance, info);
      287→    const wingsMin = ((loge.clock ? 60 : RULES.wingsBefore) + it.wait) / 60, k = kOf[N.cls] || 0;
      288→    const state = classState(N.cls, it.start, { plan, loge, cost: costSoFar[N.cls] || 0, wingsMin, k, gala });
      289→    const ex = execution(cls, info, dance, state);
      290→    // the slips: in the rehearsal nothing goes wrong but the spacing; in a try-out and on the gala night the dice roll.
      291→    // A fall on a step above the class's level can twist an ankle: she sits out the rest of the dance.
      292→    const slips = [];
      293→    if (rolls) {
      294→      for (let i = 0; i < cls.n; i++) {
      295→        let out = false;
      296→        for (const mk of dance.marks) {
      297→          if (out || info.starts[mk.k0] >= N.counts) break;
      298→          for (let k = mk.k0; k < mk.k1 && !out; k++) {
      299→            if (info.starts[k] >= N.counts) break;
      300→            if (rng() < ex.per[k].p) { const ankle = ex.per[k].gap >= 1 && rng() < RULES.ankle; slips.push({ i, r: 0, k, kind: ankle ? 'ankle' : 'trip' }); out = ankle; }
      301→          }
      302→          if (!out && mk.k1 > mk.k0 && rng() < ex.forget) slips.push({ i, r: 0, k: mk.k0 + Math.floor(rng() * (mk.k1 - mk.k0)), kind: 'forget' });
      303→        }
      304→      }
      305→      slips.sort((a, b) => a.k - b.k);
      306→    }
      307→    const wow = wowOf(id, np, cls, info, spacing, plan, school, dance);
      308→    const slipsN = rolls ? slips.length + slips.filter((s) => s.kind === 'ankle').length : ex.expected;
      309→    const pts = {
      310→      placement: spacing.ok ? 3 : !spacing.collide.length && !spacing.offstage.length && !spacing.bump.length ? 1 : 0,
      311→      music: music.ok ? 2 : 0, harmony: Math.round(info.avgHarmony * 3), execution: Math.max(0, 4 - Math.round(slipsN)), wow: wow.pts,
      312→    };
      313→    const total = Object.values(pts).reduce((s, x) => s + x, 0);
      314→    perf[id] = { id, cls: N.cls, dance, info, spacing, music, state, ex, slips, wow, pts, total, max: 17, risk: ex.expected < 0.5 ? 'low' : ex.expected < 1.5 ? 'mid' : 'high' };
      315→    costSoFar[N.cls] = (costSoFar[N.cls] || 0) + 0.012 * dance.moves.reduce((s, mid) => s + MOVES[mid].d * MOVES[mid].c, 0) * (info.avgDiff > cls.exp + 0.3 ? 1.5 : 1);
      316→    kOf[N.cls] = k + 1;
      317→  }
      318→  const gouter = judgeGouter(plan, rules, order);
      319→  const parking = rules.parking ? judgeParking(plan, school, rules, order.start) : null;
      320→
      321→  // the parents: how many came, where they sat, how they felt
      322→  const audience = Math.round(totalDancers * 2.5) + 8 * (season - 1), seats = seatsOf(school), standing = Math.max(0, audience - seats);
      323→  const sat = [['base', 60]];
      324→  if (standing) sat.push(['standing', -Math.min(20, standing)]);
      325→  if (school.upgrades.confort) sat.push(['comfy', 10]);
      326→  if (school.upgrades.buvette) sat.push(plan.interval >= 900 ? ['buvette', 10] : ['buvetteShort', 4]);
      327→  if (order.late) sat.push(['late', -15]);
      328→  if (order.startLate) sat.push(['startLate', -5]);
      329→  if (order.yawns.length) sat.push(['yawns', -5 * order.yawns.length]);
      330→  if (parking) {
      331→    if (parking.lateParents) sat.push(['lateParents', -Math.min(20, parking.lateParents)]);
      332→    if (parking.narrow) sat.push(['narrow', -5]);
      333→    if (parking.doors >= 45 && !school.upgrades.buvette) sat.push(['longWait', parking.doors >= 60 ? -10 : -5]);
      334→  }
      335→  const showQ = nums.length ? mean(nums.map((it) => perf[it.id].total / 17)) : 0;
      336→  sat.push(['show', Math.round(showQ * 20)]);
      337→  if (school.upgrades.projecteurs) sat.push(['lights', 5]);
      338→  const satisfaction = clamp(sat.reduce((s, l) => s + l[1], 0), 0, 100);
      339→
      340→  // the points: what the evening earns (a rehearsal shows what it would have earned)
      341→  const pts = [];
      342→  for (const it of nums) pts.push([`num:${it.id}`, perf[it.id].total]);
      343→  pts.push(['onTime', order.late ? 0 : 10], ['bedtime', order.sleepy ? 0 : 5], ['noWait', order.waits.length ? 0 : 5], ['startOk', order.startLate ? 0 : 5]);
      344→  if (rules.moods) pts.push(['noYawn', order.yawns.length ? 0 : 5]);
      345→  pts.push(['gouter', gouter.ok ? 10 : 0]); if (gouter.ok && gouter.variety) pts.push(['variety', 3 * gouter.variety]);
      346→  if (parking) pts.push(['parking', parking.ok ? 10 : 0]);
      347→  pts.push(['parents', Math.round(satisfaction / 5)]);
      348→  const allOk = order.ok && gouter.ok && (!parking || parking.ok) && nums.every((it) => perf[it.id].spacing.ok && perf[it.id].music.ok);
      349→  if (allOk) pts.push(['perfect', 20]);
      350→  const points = pts.reduce((s, p) => s + p[1], 0);
      351→
      352→  /* ---- the trace and every dancer's schedule, for playback ---- */
      353→  const at = (id) => order.items.find((i) => i.id === id);
      354→  const numbersOf = (c) => nums.filter((it) => NUMBERS[it.id].cls === c);
      355→  // the hair: the stations work through the dancers in the order of their classes' first number
      356→  const hairOrder = [...rules.classes].sort((a, b) => (numbersOf(a)[0]?.start ?? 1e9) - (numbersOf(b)[0]?.start ?? 1e9));
      357→  const hairDone = {}; let hairAcc = 0;
      358→  for (const c of hairOrder) for (let i = 0; i < CLS[c].n; i++) { hairAcc += HAIRS[plan.hair[c] || 'queue'].min; hairDone[dancerId(c, i)] = RULES.hairStart + Math.ceil(hairAcc / loge.postes) * 60; }
      359→  let idx = 0;
      360→  for (const c of rules.classes) {
      361→    const mine = numbersOf(c);
      362→    for (let i = 0; i < CLS[c].n; i++, idx++) {
      363→      const id = dancerId(c, i), s = (seg[id] = []), first = mine[0] ? mine[0].id : null, tArr = RULES.arrive + idx * 25;
      364→      s.push({ t: tArr, spot: ['drop', idx], act: 'arrive', cos: first }); push(tArr, `dancer:${id}`, 'arrive', 'ok');
      365→      s.push({ t: tArr + 20, spot: ['foyer', idx], act: 'walk', cos: first });
      366→      s.push({ t: RULES.warmUp, spot: ['foyer', idx], act: 'warm', cos: first });
      367→      s.push({ t: RULES.hairStart, spot: ['dr', idx], act: 'hair', cos: first });
      368→      s.push({ t: hairDone[id], spot: ['dr', idx], act: 'dress', cos: first });
      369→      s.push({ t: hairDone[id] + 240, spot: ['dr', idx], act: 'wait', cos: first });
      370→      mine.forEach((it, k) => {
      371→        const tw = it.start - it.wait - (loge.clock ? 60 : RULES.wingsBefore);
      372→        s.push({ t: tw, spot: ['wing', id], act: 'wings', cos: it.id });
      373→        if (it.wait) s.push({ t: it.start - it.wait, spot: ['wing', id], act: 'notready', cos: it.id });
      374→        s.push({ t: it.start, spot: ['stage', id, it.id], act: 'dance', item: it.id, cos: it.id }); push(it.start, `dancer:${id}`, 'dance', 'ok');
      375→        const next = mine[k + 1];
      376→        if (next) { s.push({ t: it.end, spot: ['dr', idx], act: 'change', cos: it.id }); s.push({ t: it.end + (next.change ? next.change.min * 60 : 300), spot: ['dr', idx], act: 'wait', cos: next.id }); }
      377→        else s.push({ t: it.end, spot: ['dr', idx], act: 'wait', cos: it.id });
      378→      });
      379→      const last = mine.length ? mine[mine.length - 1].id : first;
      380→      if (c === 'petits') {
      381→        if (order.sleepy) s.push({ t: RULES.bedtime, spot: null, act: 'sleepy', until: order.lastEnd.petits });
      382→      } else {
      383→        s.push({ t: finale.start - 150, spot: ['wing', id], act: 'wings', cos: last });
      384→        s.push({ t: finale.start, spot: ['finale', id], act: 'bow', cos: last }); push(finale.start, `dancer:${id}`, 'bow', 'ok');
      385→        s.push({ t: finale.end, spot: ['dr', idx], act: 'wait', cos: last });
      386→      }
      387→    }
