 14→/* ---------------- what she owns ---------------- */
 15→// kind: 'outfit' | 'hair' | 'shoes' | 'acc' | 'piece' | 'snack' | 'up' (hall and car park) | 'food'
 16→const CATALOG = { outfit: OUTFITS, hair: HAIRS, shoes: SHOES, acc: ACCS, piece: PIECES, snack: SNACKS };
 17→export function isOwned(school, kind, id) {
 18→  if (kind === 'up') return !!school.upgrades[id];
 19→  const item = CATALOG[kind] ? CATALOG[kind][id] : null;
 20→  if (kind === 'food') return !!school.owned[`food:${id}`];
