 61→    ...fx, postesRaw: fx.postes, postes: Math.max(1, fx.postes), calmRaw: fx.calm, calm: Math.min(30, fx.calm),
 62→    railCap: fx.rail * RULES.railCap, covered, tiles, clutter: covered / tiles > 0.5, invalid, totalDancers,
 63→    seatRatio: Math.min(1, fx.seats / Math.max(1, totalDancers)),
