content:         1→// The side sheet: the preparations (one tab per problem), the live evening, the verdicts, the shop. Everything she sets is
        2→// written into G.S.plan or G.S.school, saved, and the day is simulated again from scratch.
        3→import { G, save, resetAll } from './state.js';
        4→import {
        5→  RULES, CLS, NUMBERS, numDur, itemKind, STYLES, MOVES, MAX_MOVES, LEVELS, OUTFITS, HAIRS, SHOES, ACCS, PIECES, LOGE, SNACKS, UPGRADES,
        6→  BACKDROPS, PARKING, COLORS, seasonRules, hm,
        7→} from './data.js';
        8→import { simulate, routineInfo, danceOf, judgeMusic, stageOf, isOwned, fits, againstWall, footprint, analyseLoge, clamp, seatsOf } from './engine.js';
        9→import { addSeasonNumbers } from './plan.js';
       10→import { t, nm, clsName, numName, dancerName, moveName, itemName, styleName, clockOf, durOf, num } from './i18n.js';
       11→import * as W from './world.js';
       12→import { wake } from './music.js';
       13→import { TUNES } from './tunes.js';
       14→import { clean } from './words.js';
       15→import { dancers, buildDancers, redressAll, idle, idleScene, startRun, stepRun, skipNumber, fastForward, snapDancers } from './play.js';
       16→
       17→const $ = (s) => document.querySelector(s);
       18→const sheet = $('#sheet'), sbody = $('#sbody'), tabsEl = $('#tabs'), goEl = $('#go'), toastEl = $('#toast'), camBar = $('#cam'), modal = $('#modal'), floatEl = $('#float');
       19→export const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
       20→let toastT; export function toast(text) { toastEl.textContent = text; toastEl.classList.add('show'); clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('show'), 2600); }
       21→const rules = () => seasonRules(G.S.season);
       22→const activeNums = () => G.S.plan.order.filter((id) => NUMBERS[id] && rules().classes.includes(NUMBERS[id].cls));
       23→const forecast = () => simulate({ plan: G.S.plan, school: G.S.school, season: G.S.season, mode: 'rehearsal', seed: G.S.seed });
