      236→    np.blocks.push({ id: free, name: `${blk.name} 2`.slice(0, 24), moves: [...blk.moves] }); selBlock[id] = free; selMove = null; changed();
      237→  };
      238→  sbody.querySelector('#renBlk').onclick = () => {
