      253→  for (const b of sbody.querySelectorAll('[data-ch]')) b.onclick = () => { selChain = selChain === +b.dataset.ch ? null : +b.dataset.ch; paintFormation(); };
      254→  sbody.querySelector('#addCh').onclick = () => { if (np.chain.length >= MAX_CHAIN) { toast(t().maxChain); return; } np.chain.push(bid); changed(); };
      255→  for (const b of sbody.querySelectorAll('[data-cm]')) b.onclick = () => {
