      266→// the music above, the dance below: each block of the chain in its colour, red where it runs past the music
      267→function musicBar(id, np, dance, info) {
      268→  const N = NUMBERS[id], scale = Math.max(N.counts, info.phrase, 1), W0 = 100;
      269→  let blocks = '';
      270→  for (const mk of dance.marks.slice(0, 120)) {
      271→    if (mk.k1 === mk.k0) continue;
      272→    const s0 = info.starts[mk.k0], s1 = info.starts[mk.k1 - 1] + MOVES[dance.moves[mk.k1 - 1]].c, x0 = (s0 / scale) * W0, x1 = Math.min((s1 / scale) * W0, W0);
      273→    blocks += `<rect x="${x0}" y="9" width="${Math.max(0.2, x1 - x0 - 0.25)}" height="6" rx="1" fill="${s1 > N.counts ? '#ff6f6f' : blockColor(np, mk.block)}"/>`;
      274→  }
      275→  const mW = (N.counts / scale) * W0;
      276→  return `<svg class="musicbar" viewBox="-1 0 102 22" role="img" aria-label="${esc(t().musicBar)}"><text x="0" y="3.6">${esc(t().musicBar)}</text><rect x="0" y="4.5" width="${mW}" height="3.2" rx="1" fill="#f5b942"/><text x="0" y="20.5">${esc(t().yourDance)}</text>${blocks}<line x1="${mW}" x2="${mW}" y1="3" y2="16" stroke="#fff" stroke-width=".3" stroke-dasharray="1 .6"/></svg>`;
      277→}
      278→function forecastBox(P, cls) {
      279→  const s = P.state, meter = (label, v, good) => { const ok = good === 'high' ? v >= 60 : v <= 40, bad = good === 'high' ? v < 40 : v > 60; return `<div class="meter"><span>${esc(label)}</span><span class="bar"><i style="width:${v}%;background:${ok ? 'var(--good)' : bad ? 'var(--bad)' : 'var(--warn)'}"></i></span><b>${v}</b></div>`; };
      280→  const reasons = riskReasons(P, cls);
      281→  return `<h3>${esc(t().forecastH)}</h3><div class="meters">${meter(t().energy, s.energy, 'high')}${meter(t().hunger, s.hunger, 'low')}${meter(t().nerves, s.nerves, 'low')}${meter(t().focus, s.focus, 'high')}</div>`
      282→    + `<p class="risk ${P.risk}">${esc(t().risk[P.risk])}</p>${reasons.length ? `<ul class="facts">${reasons.map((r) => `<li>${esc(r)}</li>`).join('')}</ul>` : ''}`;
      283→}
      284→function riskReasons(P, cls) {
      285→  const S = t().sum, out = [], ex = P.ex;
      286→  for (const x of ex.per) if (x.gap >= 1 && !out.some((o) => o.includes(moveName(x.id)))) out.push(S.tooHard(moveName(x.id), MOVES[x.id].d, cls.exp));
      287→  if (ex.per.some((x) => x.streak)) out.push(S.streak);
      288→  if (ex.bored > 0) out.push(S.bored(num(P.info.avgDiff), cls.exp));
      289→  if (ex.long) out.push(S.longRep(P.dance.mostRepeated));
      290→  if (ex.shoe > 1) out.push(S.pointes);
      291→  if (P.state.energy < 55) out.push(`${t().energy} ${P.state.energy}`);
      292→  if (P.state.hunger > 50) out.push(`${t().hunger} ${P.state.hunger}`);
      293→  if (P.state.nerves > 50) out.push(`${t().nerves} ${P.state.nerves}`);
      294→  if (P.state.focus < 55) out.push(`${t().focus} ${P.state.focus}`);
      295→  return out.slice(0, 6);
      296→}
      297→// the stage seen from above: the audience at the bottom, metres from the middle along the front, metres back up the side
      298→function stagePlanSvg(id, np, cls, st, info, pathMoves) {
      299→  const Wd = st.halfW, D = st.depth, F = G.editB && np.B ? np.B : np.A, col = np.costume.color === '#ffffff' ? '#e8e2f5' : np.costume.color;
      300→  let s = `<svg class="stageplan" id="plan" viewBox="${-Wd - 0.9} -0.5 ${2 * Wd + 1.8} ${D + 1.7}" role="img" aria-label="stage">`;
      301→  s += `<rect x="${-Wd - 0.9}" y="-0.5" width="0.9" height="${D + 0.5}" fill="#1b1720"/><rect x="${Wd}" y="-0.5" width="0.9" height="${D + 0.5}" fill="#1b1720"/>`;
      302→  s += `<rect x="${-Wd}" y="0" width="${2 * Wd}" height="${D}" fill="none" stroke="rgba(255,255,255,.4)" stroke-width="0.04"/>`;
      303→  for (let x = -Wd; x <= Wd + 1e-9; x += 0.5) for (let z = 0; z <= D + 1e-9; z += 0.5) s += `<circle cx="${x}" cy="${D - z}" r="${Number.isInteger(x) && Number.isInteger(z) ? 0.05 : 0.03}" fill="rgba(255,255,255,${Number.isInteger(x) && Number.isInteger(z) ? 0.5 : 0.28})"/>`;
      304→  for (let x = Math.ceil(-Wd); x <= Wd; x++) s += `<text class="lbl" x="${x}" y="${D + 0.32}">${Math.abs(x)}</text>`;
      305→  for (let z = 1; z <= D; z++) s += `<text class="lbl" x="${-Wd - 0.45}" y="${D - z}">${z}</text>`;
      306→  s += `<text x="0" y="${D + 0.85}" class="aud">▼ ${esc(t().audience)} ▼</text>`;
      307→  // the selected dancer's arms and her path through one phrase
      308→  const sel = G.pickDancer;
      309→  if (sel !== null && F[sel]) {
      310→    const p = F[sel], r = cls.span / 2;
      311→    let path = `${p.x},${D - p.z}`, x = p.x, z = p.z, cur = F, other = cur === np.A ? (np.B || np.A) : np.A;
      312→    pathMoves.forEach((mid) => { const m = MOVES[mid]; if (m.swap && np.B) { x += other[sel].x - cur[sel].x; z += other[sel].z - cur[sel].z; [cur, other] = [other, cur]; } x += m.dx || 0; z += m.dz || 0; path += ` ${x},${D - z}`; });
      313→    s += `<polyline points="${path}" fill="none" stroke="#7cc6ff" stroke-width="0.05" stroke-dasharray="0.15 0.1"/>`;
      314→    s += `<circle cx="${p.x}" cy="${D - p.z}" r="${r}" fill="rgba(245,185,66,.12)" stroke="#f5b942" stroke-width="0.04" stroke-dasharray="0.12 0.08"/>`;
      315→    s += `<line x1="${p.x - r}" y1="${D - p.z}" x2="${p.x + r}" y2="${D - p.z}" stroke="#f5b942" stroke-width="0.07"/><circle cx="${p.x - r}" cy="${D - p.z}" r="0.08" fill="#f5b942"/><circle cx="${p.x + r}" cy="${D - p.z}" r="0.08" fill="#f5b942"/>`;
      316→    s += `<text class="lbl gold" x="${p.x}" y="${D - p.z - r - 0.14}">${esc(t().arms)}</text>`;
      317→  }
      318→  s += F.map((p, i) => `<g data-dot="${i}" style="cursor:grab"><circle cx="${p.x}" cy="${D - p.z}" r="0.3" fill="${col}" stroke="${sel === i ? '#f5b942' : '#fff'}" stroke-width="${sel === i ? 0.09 : 0.05}"/><text x="${p.x}" y="${D - p.z}">${i + 1}</text></g>`).join('');
      319→  if (G.ruler) {
      320→    const R = G.ruler, L = 3; let ticks = '';
      321→    for (let k = 0; k <= 30; k++) { const big = k % 5 === 0; ticks += `<line x1="${k / 10}" y1="0" x2="${k / 10}" y2="${big ? 0.2 : k % 5 ? 0.09 : 0.14}" stroke="#2b2236" stroke-width="${big ? 0.025 : 0.015}"/>`; if (big) ticks += `<text class="rl" x="${k / 10}" y="0.3">${num(k / 10)}</text>`; }
      322→    s += `<g id="ruler" transform="translate(${R.x} ${D - R.z}) rotate(${-R.a})"><rect x="-0.08" y="-0.02" width="${L + 0.16}" height="0.42" rx="0.03" fill="#ffe7a8" stroke="#2b2236" stroke-width="0.02" style="cursor:move"/>${ticks}<circle id="rulerTurn" cx="${L + 0.25}" cy="0.2" r="0.16" fill="#f5b942" stroke="#2b2236" stroke-width="0.02" style="cursor:alias"/></g>`;
      323→  }
      324→  return s + '</svg>';
      325→}
      326→function bindStagePlan(root, id, np, cls, st, info) {
      327→  const svg = root.querySelector('#plan'), D = st.depth, Wd = st.halfW; let drag = null, moved = false, rDrag = null;
      328→  const toPlan = (e) => { const pt = svg.createSVGPoint(); pt.x = e.clientX; pt.y = e.clientY; const q = pt.matrixTransform(svg.getScreenCTM().inverse()); return { x: q.x, z: D - q.y }; };
      329→  const F = () => (G.editB && np.B ? np.B : np.A);
      330→  for (const g of svg.querySelectorAll('[data-dot]')) g.addEventListener('pointerdown', (e) => { drag = +g.dataset.dot; moved = false; svg.setPointerCapture(e.pointerId); e.preventDefault(); e.stopPropagation(); });
      331→  const ruler = svg.querySelector('#ruler');
      332→  if (ruler) {
      333→    ruler.querySelector('rect').addEventListener('pointerdown', (e) => { const q = toPlan(e); rDrag = { kind: 'move', dx: q.x - G.ruler.x, dz: q.z - G.ruler.z }; svg.setPointerCapture(e.pointerId); e.preventDefault(); e.stopPropagation(); });
      334→    ruler.querySelector('#rulerTurn').addEventListener('pointerdown', (e) => { rDrag = { kind: 'turn' }; svg.setPointerCapture(e.pointerId); e.preventDefault(); e.stopPropagation(); });
      335→  }
      336→  svg.addEventListener('pointermove', (e) => {
      337→    const q = toPlan(e);
      338→    if (rDrag) {
      339→      if (rDrag.kind === 'move') { G.ruler.x = q.x - rDrag.dx; G.ruler.z = q.z - rDrag.dz; }
      340→      else G.ruler.a = Math.round(Math.atan2(q.z - G.ruler.z, q.x - G.ruler.x) * 180 / Math.PI / 5) * 5;
      341→      ruler.setAttribute('transform', `translate(${G.ruler.x} ${D - G.ruler.z}) rotate(${-G.ruler.a})`); return;
      342→    }
      343→    if (drag === null) return; moved = true;
      344→    const g = svg.querySelector(`[data-dot="${drag}"]`); g.querySelector('circle').setAttribute('cx', q.x); g.querySelector('circle').setAttribute('cy', D - q.z); g.querySelector('text').setAttribute('x', q.x); g.querySelector('text').setAttribute('y', D - q.z);
      345→  });
      346→  const drop = (e) => {
      347→    if (rDrag) { rDrag = null; return; }
      348→    if (drag === null) return; const i = drag; drag = null;
      349→    if (moved) { const q = toPlan(e); F()[i] = { x: clamp(Math.round(q.x * 2) / 2, -Wd - 0.5, Wd + 0.5), z: clamp(Math.round(q.z * 2) / 2, 0, D) }; }
      350→    G.pickDancer = i; changed();
      351→  };
      352→  svg.addEventListener('pointerup', drop); svg.addEventListener('pointercancel', () => { drag = null; rDrag = null; paintFormation(); });
      353→}
