      359→  for (const [id, s] of Object.entries(SNACKS)) { const own = isOwned(sc, 'snack', id); h += `<button type="button" data-snack="${id}" aria-pressed="${P.snack === id}" class="${own ? '' : 'locked'}"><span>${s.icon}</span>${esc(nm(s))}<small>${esc(own ? t().snackFx[id] : t().buy(s.price))}</small></button>`; }
      360→  h += `</div><h3>${esc(t().vGouter)}</h3>${facts([...t().gouterFacts, ...(sc.owned['food:crepes'] ? [t().crepeFact] : []), ...(sc.owned['food:compotes'] ? [t().compoteFact] : [])])}`;
      361→  h += `<table class="kc"><tr>${t().kTable.map((x) => `<th>${esc(x)}</th>`).join('')}</tr>${cl.map((c) => `<tr><td>${esc(clsName(c))} <span class="muted">(${CLS[c].age})</span></td><td>${CLS[c].n}</td><td>${CLS[c].kcal} kcal</td><td>${CLS[c].juice} cl</td></tr>`).join('')}</table>`;
      362→  h += stepper('cake', t().cake, `${P.cakeG} g`) + stepper('bottles', t().bottles, String(P.bottles));
