252→  for (const b of sbody.querySelectorAll('[data-add]')) b.onclick = () => { if (blk.moves.length >= MAX_MOVES) { toast(t().maxMoves); return; } blk.moves.push(b.dataset.add); changed(); };
253→  for (const b of sbody.querySelectorAll('[data-ch]')) b.onclick = () => { selChain = selChain === +b.dataset.ch ? null : +b.dataset.ch; paintFormation(); };
