content:         1→// Playback: the day the engine computed, drawn. Nothing here decides anything; it reads simulate()'s schedule and verdicts.
        2→import * as T from 'three';
        3→import { G, save } from './state.js';
        4→import { CLS, NUMBERS, MOVES, RULES, itemKind, STYLES, PARKING } from './data.js';
        5→import { simulate, dancerId, routineInfo, stageOf, analyseLoge, clamp, seatsOf } from './engine.js';
        6→import {
        7→  scene, V, STAGE, ROOMS, stageToWorld, floorY, route, TABLE, curtain, drawClock, showTable, setParents, setStageFloor,
        8→  stepLights, carMesh, hideCars, placeCar, BAYS, cutTo, view, snapCam,
        9→} from './world.js';
       10→import { makeDancer, lookOf, bubbleOf, applyPose, REST } from './people.js';
       11→
       12→export const dancers = [];
       13→const dancersG = new T.Group(); scene.add(dancersG);
       14→const classes = () => G.S && simulateRules().classes;
       15→const simulateRules = () => ({ classes: Object.keys(CLS).filter((c) => CLS[c].from <= G.S.season) });
       16→const numbersOf = (cls) => G.S.plan.order.filter((id) => NUMBERS[id] && NUMBERS[id].cls === cls);
       17→
       18→/* ---------------- the people ---------------- */
       19→export function buildDancers() {
       20→  for (const d of dancers) { dancersG.remove(d.g); dancersG.remove(d.bubble); }
       21→  dancers.length = 0; let idx = 0;
       22→  for (const c of classes()) for (let i = 0; i < CLS[c].n; i++, idx++) {
       23→    const bubble = new T.Sprite(bubbleOf('🙂')); bubble.scale.set(0.55, 0.55, 1); bubble.visible = false; bubble.renderOrder = 5; dancersG.add(bubble);
       24→    const d = { id: dancerId(c, i), cls: c, i, idx, g: null, bubble, pos: V(0, 0, 30), face: 0, path: [], goal: null, goalKey: '', walkT: 0, emoji: null, lookKey: '' };
       25→    dress(d, numbersOf(c)[0]); dancers.push(d);
       26→  }
       27→}
       28→// put on number numId's costume (and the class's hair); rebuild the mesh only when something changed
       29→export function dress(d, numId) {
       30→  const np = numId && G.S.plan.numbers[numId], cos = np ? np.costume : { outfit: 'justaucorps', color: CLS[d.cls].color, shoes: 'demi', acc: 'aucun' };
       31→  const hair = G.S.plan.hair[d.cls] || 'queue', key = JSON.stringify([cos, hair]);
       32→  if (key === d.lookKey && d.g) return;
       33→  const was = d.g; d.lookKey = key; d.g = makeDancer(lookOf(d.cls, d.i), cos, hair, CLS[d.cls].scale);
       34→  if (was) { d.g.position.copy(was.position); d.g.rotation.y = was.rotation.y; d.g.visible = was.visible; dancersG.remove(was); }
       35→  dancersG.add(d.g);
       36→}
       37→export const redressAll = () => { for (const d of dancers) { d.lookKey = ''; dress(d, d.wearing || numbersOf(d.cls)[0]); } };
       38→
       39→/* ---------------- where each spot is ---------------- */
       40→function spotPos(spot, d) {
       41→  const [kind] = spot, idx = d.idx;
       42→  if (kind === 'drop') return V(7 + (spot[1] % 4) * 0.6, 0, 9.4 + (Math.floor(spot[1] / 4) % 2) * 0.6);
       43→  if (kind === 'foyer') return V(3.8 + (idx % 10) * 0.9, 0, Math.floor(idx / 10) * 0.9);
       44→  if (kind === 'dr') { const per = G.S.school.logeCols - 1; return V(3.6 + (idx % per) * 1.0, 0, -8.3 + Math.floor(idx / per) * 1.4); }
       45→  if (kind === 'wing') return V(0.5 + (d.i % 3) * 0.85, STAGE.h, -8.4 + Math.floor(d.i / 3) * 1.25);
       46→  if (kind === 'finale') {
       47→    const rows = classes().filter((c) => c !== 'petits'), k = rows.indexOf(d.cls), n = CLS[d.cls].n, sp = Math.min(1.25, 10.5 / n);
       48→    return stageToWorld((d.i - (n - 1) / 2) * sp + (k % 2) * 0.3, 0.5 + k * (4.6 / Math.max(1, rows.length)));
       49→  }
       50→  if (kind === 'table') return V(4.3 + (idx % 10) * 0.95, 0, 0.4 + Math.floor(idx / 10) * 1.1);
       51→  if (kind === 'podium') { const n = CLS[d.cls].n; return stageToWorld((d.i - (n - 1) / 2) * Math.min(1.15, 10.5 / n), 0.5); }
       52→  return V(8, 0, 2);
       53→}
       54→
       55→/* ---------------- dancing: each move has its own shape, on its counts ---------------- */
       56→const S = Math.sin, PI = Math.PI, hump = (u) => S(PI * clamp(u, 0, 1));
       57→const walk = (u) => ({ lL: 0.5 * S(4 * PI * u), lR: -0.5 * S(4 * PI * u), afL: -0.4 * S(4 * PI * u), afR: 0.4 * S(4 * PI * u), aL: 0.1, aR: 0.1 });
       58→const hop = (u) => ({ aL: 1.5, aR: 1.5, y: 0.08 * Math.abs(S(4 * PI * u)), lL: 0.35 * S(4 * PI * u), lR: -0.35 * S(4 * PI * u) });
       59→export const MOVE_POSE = {
       60→  plie: (u) => ({ aL: 0.9, aR: 0.9, sit: 0.25 * hump(u) }),
       61→  releve: (u) => ({ aL: 0.9 + 2.0 * u, aR: 0.9 + 2.0 * u, y: 0.12 * u }),
       62→  bras: (u) => ({ aL: 0.3 + 2.5 * hump(u), aR: 0.3 + 2.5 * hump(u), afL: 0.6 * S(2 * PI * u), afR: 0.6 * S(2 * PI * u), side: 0.15 * S(2 * PI * u) }),
       63→  chasseD: hop, chasseG: hop, avance: walk, recule: walk, echange: walk,
       64→  tourne: (u) => ({ aL: 1.2, aR: 1.2, spin: 2 * PI * u }),
       65→  saute: (u) => ({ aL: 0.6, aR: 0.6, y: 0.22 * Math.abs(S(4 * PI * u)), lL: 0.2 * Math.abs(S(4 * PI * u)), lR: 0.2 * Math.abs(S(4 * PI * u)) }),
       66→  reception: (u) => ({ aL: 1.5 - 0.8 * u, aR: 1.5 - 0.8 * u, y: 0.25 * (1 - u) * (1 - u), sit: 0.2 * hump(u) }),
       67→  clap: (u) => { const k = Math.abs(S(4 * PI * u)); return { afL: 1.4, afR: 1.4, aL: -0.15 + 0.5 * k, aR: -0.15 + 0.5 * k, y: 0.04 * k }; },
       68→  vague: (u) => ({ bow: 0.3 * S(2 * PI * u), side: 0.2 * S(4 * PI * u), afL: 0.8 + 0.5 * S(2 * PI * u + 1), afR: 0.8 + 0.5 * S(2 * PI * u + 2), aL: 0.4, aR: 0.4 }),
       69→  descente: (u) => ({ sit: u, aL: 0.6 + 0.6 * u, aR: 0.6 + 0.6 * u, bow: 0.2 * hump(u) }),
       70→  remonte: (u) => ({ sit: 1 - u, aL: 1.2, aR: 1.2 }),
       71→  pirouette: (u) => ({ aL: 2.4, aR: 2.4, afL: 0.6, afR: 0.6, y: 0.12, spin: 4 * PI * u, lR: 0.5 }),
       72→  arabesque: (u) => ({ lR: -1.3 * hump(u * 1.3), bow: 0.35 * hump(u), afL: 1.3, aL: 0.6, aR: 1.6, y: 0.06 }),
       73→  sautChat: (u) => ({ y: 0.45 * hump(u), lL: 1.0 * hump(u), lR: 0.8 * hump(u), aL: 2.2 * hump(u) + 0.4, aR: 2.2 * hump(u) + 0.4 }),
       74→  kick: (u) => ({ lL: 1.6 * hump(u * 2), lR: 1.6 * hump(u * 2 - 1), aL: 1.6, aR: 1.6 }),
       75→  roulade: (u) => ({ sit: 1, roll: 2 * PI * u, aL: 1.0, aR: 1.0 }),
       76→  moonwalk: (u) => ({ lL: 0.4 * S(4 * PI * u), lR: -0.4 * S(4 * PI * u), y: 0.03, afL: 0.3 * S(4 * PI * u), afR: -0.3 * S(4 * PI * u), aL: 0.2, aR: 0.2, bow: -0.08 }),
       77→  toprock: (u) => ({ lL: 0.45 * S(4 * PI * u), lR: -0.45 * S(4 * PI * u), afL: 0.7 * S(4 * PI * u), afR: -0.7 * S(4 * PI * u), aL: 0.4, aR: 0.4, y: 0.05 * Math.abs(S(4 * PI * u)), side: 0.12 * S(4 * PI * u) }),
       78→  grandJete: (u) => ({ y: 0.7 * hump(u), lL: 1.3 * hump(u), lR: -1.3 * hump(u), aL: 1.7, aR: 1.7, afL: 0.8 * hump(u), afR: 0.3 }),
       79→  fouette: (u) => ({ spin: 6 * PI * u, lR: 1.2 * Math.abs(S(6 * PI * u)), aL: 1.5, aR: 1.5, y: 0.12 }),
       80→  freeze: (u) => ({ sit: 1, side: 0.9 * Math.min(1, u * 3), aR: 2.6, lL: 0.4, lR: 0.9 }),
       81→  reverence: (u) => ({ bow: 0.5 * hump(u), sit: 0.18 * hump(u), aL: 0.7, aR: 0.7, afL: 0.3, afR: 0.3 }),
       82→};
       83→// where dancer i of a number is, and what she is doing, at count c
       84→// np: the flat dance (perf.dance), played once through
       85→export function danceAt(numId, np, info, i, c, slips) {
       86→  const A = np.A, B = np.B || np.A, total = np.repeats * info.phrase;
       87→  if (!info.phrase) return { x: A[i].x, z: A[i].z, pose: REST, done: true };
       88→  const hurt = slips && slips.find((s) => s.i === i && s.kind === 'ankle' && info.starts[s.k] + 1 <= c);
       89→  if (hurt) { const at = danceAt(numId, np, info, i, info.starts[hurt.k] + 1, null); return { ...at, pose: { sit: 1, bow: 0.25, aL: 0.5, aR: 0.5, lR: 0.6 }, slip: hurt, jolt: false, done: c >= total }; }
       90→  const cc = Math.min(c, total - 1e-6), r = Math.floor(cc / info.phrase), pc = cc - r * info.phrase;
       91→  let k = 0; while (k + 1 < np.moves.length && info.starts[k + 1] <= pc) k++;
       92→  const m = MOVES[np.moves[k]], u = clamp((pc - info.starts[k]) / m.c, 0, 1);
       93→  const swapsBefore = r * info.swaps + np.moves.slice(0, k).filter((id) => MOVES[id].swap).length, F = swapsBefore % 2 ? B : A, Gf = F === A ? B : A;
       94→  const prev = k ? info.offsets[k - 1] : { dx: 0, dz: 0 }, ox = r * info.net.dx + prev.dx + u * (m.dx || 0), oz = r * info.net.dz + prev.dz + u * (m.dz || 0);
       95→  let x = F[i].x, z = F[i].z; if (m.swap && np.B) { x += (Gf[i].x - x) * u; z += (Gf[i].z - z) * u; }
       96→  const slip = slips && slips.find((s) => s.i === i && s.r === r && s.k === k);
       97→  // a step a grown-up added moves like the step it was given ("moves like", settings)
       98→  let pose = (MOVE_POSE[np.moves[k]] || MOVE_POSE[m.like] || (() => REST))(u);
       99→  if (slip && slip.kind === 'trip' && u > 0.3) pose = { sit: 1, bow: -0.35, aL: 1.6, aR: 1.6 };
      100→  if (slip && slip.kind === 'forget') pose = { aR: 2.7, afR: 0.4, aL: 0.1, side: 0.1 };
      101→  const link = k > 0 ? info.links[k - 1] : null;
      102→  return { x: x + ox, z: z + oz, pose, slip, jolt: !!link && link.gap === 2 && u < 0.35, done: c >= total, k, r };
      103→}
