      105→/* ---------------- the run ---------------- */
      106→let toastFn = () => {}, sayFn = () => '';
      107→export function onSay(fn, toast) { sayFn = fn; toastFn = toast; }
      108→export function startRun(mode, tryId) {
      109→  if (mode === 'gala' && G.S.galaDone) return null;
      110→  // a try-out rolls its own dice every time; the gala keeps the season's seed
      111→  const res = simulate({ plan: G.S.plan, school: G.S.school, season: G.S.season, mode, seed: mode === 'try' ? (Math.random() * 1e9) >>> 0 : G.S.seed });
      112→  const run = { mode, res, t: Math.min(RULES.arrive - 300, res.doors - 300), i: 0, done: false, feed: [], tryId, auto: '' };
      113→  if (mode === 'try') {
      114→    const it = res.order.items.find((x) => x.id === tryId); run.t = it.start - 4; run.endT = it.end + 3; run.item = it;
      115→    run.i = res.trace.findIndex((e) => e.t >= run.t); if (run.i < 0) run.i = res.trace.length;
      116→  } else run.endT = res.end;
      117→  for (const d of dancers) { d.goalKey = ''; d.path = []; d.emoji = null; d.g.visible = false; d.bubble.visible = false; d.pos.set(0, 0, 30); }
      118→  hideCars(); setParents(0);
      119→  showTable(1, G.S.plan.bottles, G.S.plan.crepes);
      120→  G.run = run; G.speed = 1;
      121→  if (mode === 'try') cutTo('stage');
      122→  return run;
      123→}
      124→function rateAt(t) {
      125→  const run = G.run, R = run.res; if (run.mode === 'try') return (60 / NUMBERS[run.tryId].bpm) * RULES.countsPerSec;
      126→  if (t < R.doors - 300) return 300; if (t >= R.finalEnd) return 50;
      127→  const it = R.order.items.find((i) => t >= i.start && t < i.end); if (!it) return 90;
      128→  if (it.kind === 'number') return (60 / NUMBERS[it.id].bpm) * RULES.countsPerSec;
      129→  return it.kind === 'finale' ? 20 : it.kind === 'interval' ? 200 : 80;
      130→}
      131→export function stepRun(dt) {
      132→  const run = G.run; if (!run || run.done) return;
      133→  const R = run.res; run.t += dt * rateAt(run.t) * G.speed;
      134→  while (run.i < R.trace.length && R.trace[run.i].t <= run.t) {
      135→    const e = R.trace[run.i++]; if (!e.say) continue;
      136→    if (run.mode === 'try' && !(e.who === `number:${run.tryId}`)) continue;
      137→    const text = sayFn(e.say, R); run.feed.push({ t: e.t, text }); toastFn(text);
      138→  }
      139→  // the camera follows the numbers when she asked it to
      140→  if (G.follow && run.mode !== 'try') {
      141→    const it = R.order.items.find((i) => run.t >= i.start - 20 && run.t < i.end + 4), want = it && (it.kind === 'number' || it.kind === 'finale') ? 'stage' : 'school';
      142→    if (want !== run.auto) { run.auto = want; if (view.mode !== want) { G.pickedRoom = null; cutTo(want); } }
      143→  }
      144→  if (run.t >= run.endT) { run.done = true; run.onDone && run.onDone(); }
      145→}
      146→export const currentItem = () => { const run = G.run; if (!run) return null; return run.res.order.items.find((i) => run.t >= i.start && run.t < i.end) || null; };
      147→export function skipNumber() {
      148→  const run = G.run; if (!run) return; const it = currentItem();
      149→  const target = it && (it.kind === 'number' || it.kind === 'finale' || it.kind === 'interval') ? it.end : (run.res.order.items.find((i) => i.start > run.t) || { start: run.endT }).start;
      150→  fastForward(Math.max(1, target - run.t + 0.5));
      151→}
      152→export function fastForward(sec) { const run = G.run; if (!run) return; const end = Math.min(run.endT, run.t + sec); while (G.run && !run.done && run.t < end) { const r = rateAt(run.t) * G.speed, step = Math.min(30, end - run.t); stepRun(step / r); } snapDancers(); }
      153→
      154→// a dancer's place and doing at day-time t
      155→function segmentAt(d, t) {
      156→  const s = G.run.res.seg[d.id]; if (!s) return null; let cur = null;
      157→  for (const x of s) { if (x.t > t) break; if (x.spot) cur = { ...x, sleepy: cur && cur.sleepy }; else if (x.act === 'sleepy' && cur) cur = { ...cur, sleepy: x.until }; }
      158→  return cur;
      159→}
      160→const EMO = { arrive: '👋', warm: '🤸', hair: '💇', dress: '👗', change: '👗', wings: '✨', notready: '😕', bow: '😊', eat: '🍰', pout: '😕', party: '🎉', sleepy: '😴', leave: '👋' };
      161→function needEmoji(d, run) {
      162→  const R = run.res, next = R.order.items.find((it) => it.kind === 'number' && NUMBERS[it.id].cls === d.cls && it.end > run.t);
      163→  if (!next || d.i % 3) return null; const st = R.perf[next.id].state;
      164→  if (st.hunger > 55) return '🍽️'; if (st.energy < 45) return '🥱'; if (st.focus < 45) return '🌫️'; if (st.nerves > 60) return '😬'; return null;
      165→}
      166→export function updateDancers(dt) {
      167→  const run = G.run;
      168→  for (const d of dancers) {
      169→    let act = 'wait', target = null, key = '', pose = null, emo = null;
      170→    if (run) {
      171→      const s = segmentAt(d, run.t);
      172→      if (run.mode === 'try' && d.cls !== NUMBERS[run.tryId].cls) { d.g.visible = false; d.bubble.visible = false; continue; }
      173→      if (!s || s.act === 'gone') { d.g.visible = false; d.bubble.visible = false; continue; }
      174→      if (s.cos && s.cos !== d.wearing) { d.wearing = s.cos; dress(d, s.cos); }
      175→      act = s.act;
      176→      if (act === 'dance') {
      177→        const P = run.res.perf[s.item], np = P.dance, it = run.res.order.items.find((x) => x.id === s.item);
      178→        const c = (run.t - it.start) * NUMBERS[s.item].bpm / 60, D = danceAt(s.item, np, P.info, d.i, c, P.slips);
      179→        target = stageToWorld(D.x, D.z); pose = D.done ? REST : D.pose; key = 'dance';
      180→        const sp = P.spacing;
      181→        if (D.slip) emo = D.slip.kind === 'trip' ? '😵' : D.slip.kind === 'ankle' ? '🤕' : '🤔';
      182→        else if (D.jolt) emo = '💥';
      183→        else if (sp.collide.some((x) => x.i === d.i || x.j === d.i)) emo = '😬';
      184→        else if (sp.offstage.some((x) => x.i === d.i && (x.r < D.r || (x.r === D.r && x.k <= D.k)))) emo = '😮';
      185→        else if (sp.hidden.some((x) => x.b === d.i)) emo = '🙈';
      186→        else if (D.done && P.music.diff < 0) emo = '😐';
      187→        if (!d.g.visible) { d.g.visible = true; d.pos.copy(target); }
      188→        d.pos.copy(target); d.path = []; d.goalKey = 'dance';
      189→      } else {
      190→        target = spotPos(s.spot, d); key = s.spot.join('|');
      191→        if (s.sleepy && run.t < s.sleepy && run.t >= RULES.bedtime && act !== 'bow') act = 'sleepy';
      192→        if (!d.g.visible) { d.g.visible = true; d.pos.copy(target); d.path = []; d.goalKey = key; d.goal = target.clone(); }
      193→        emo = EMO[act] || null;
      194→        if ((act === 'wait' || act === 'wings') && s.spot[0] !== 'table') emo = needEmoji(d, run) || (act === 'wings' ? '✨' : null);
      195→        if (act === 'wait' && s.spot[0] === 'dr') { const L = run.res.loge; if (d.idx >= L.seats && d.idx % 4 === 1) emo = '🪑'; }
      196→      }
      197→    } else {
      198→      target = d.idle; key = 'idle' + d.idleKey; act = d.idleAct;
      199→      d.g.visible = true;
      200→    }
      201→    if (key !== 'dance' && (key !== d.goalKey || !d.goal || d.goal.distanceTo(target) > 0.01)) { d.goalKey = key; d.goal = target.clone(); d.path = route(d.pos, target); }
      202→    let moving = false;
      203→    if (key !== 'dance' && d.path.length) {
      204→      const p = d.path[0], dx = p.x - d.pos.x, dz = p.z - d.pos.z, L = Math.hypot(dx, dz);
      205→      let rest = L; for (let k = 1; k < d.path.length; k++) rest += d.path[k].distanceTo(d.path[k - 1]);
      206→      const sp = Math.max(run ? 4.5 * Math.sqrt(G.speed) : 5, rest / 1.0) * dt;
      207→      if (L < 0.05) d.path.shift(); else { const k = Math.min(1, sp / L); d.pos.x += dx * k; d.pos.z += dz * k; d.face = Math.atan2(dx, dz); moving = true; }
      208→    }
      209→    d.pos.y = floorY(d.pos.x, d.pos.z);
      210→    const u = d.g.userData;
      211→    if (moving) { d.walkT += dt * 9; applyPose(d, walk((d.walkT / (4 * PI)) % 1)); }
      212→    else if (pose) { applyPose(d, pose); d.face = 0; }
      213→    else if (act === 'bow') { const c = (G.realT * 2) % 4; applyPose(d, { bow: c < 1 ? S(c * PI) * 0.5 : 0 }); d.face = 0; }
      214→    else if (act === 'warm') { const c = G.realT * 2 + d.i; applyPose(d, { aL: 2.6 + S(c) * 0.2, aR: 2.6 + S(c) * 0.2, side: S(c) * 0.25 }); }
      215→    else if (act === 'party') applyPose(d, { aL: 2.7, aR: 2.7, y: Math.abs(S(G.realT * 5 + d.i)) * 0.25 });
      216→    else if (act === 'sleepy') applyPose(d, { side: 0.25, aL: 0.05, aR: 0.05 });
      217→    else if (act === 'sit') applyPose(d, { sit: 0.55, aL: 0.2, aR: 0.2 });
      218→    else if (act === 'hair') applyPose(d, { aL: 0.1, aR: 0.1, bow: 0.1 });
      219→    else applyPose(d, REST);
      220→    if (!moving && !pose && act !== 'bow') d.face = act === 'eat' || act === 'pout' || act === 'party' ? Math.atan2(TABLE.x - 1 - d.pos.x, TABLE.z - d.pos.z) : run ? d.face : d.idleFace;
      221→    if (d.cls === 'petits' && !moving && !pose) u.body.rotation.z += S(performance.now() / 260 + d.i) * 0.05;
      222→    d.g.position.set(d.pos.x, d.pos.y, d.pos.z); d.g.rotation.y = d.face;
      223→    if (!run) emo = null;
      224→    if (emo !== d.emoji) { d.emoji = emo; if (emo) d.bubble.material = bubbleOf(emo); }
      225→    d.bubble.visible = !!emo && d.g.visible; d.bubble.position.set(d.pos.x + 0.25, d.pos.y + u.h + 0.35, d.pos.z);
      226→  }
      227→}
      228→export function snapDancers() { updateDancers(0.001); for (const d of dancers) if (d.goal && d.g.visible && d.goalKey !== 'dance') { d.pos.copy(d.goal); d.path = []; } updateDancers(0.001); }
