      230→/* ---------------- when nothing runs: everyone somewhere sensible, the class she is working on in front ---------------- */
      231→export function idle() {
      232→  const tab = G.tab, num = G.pickNum && G.S.plan.numbers[G.pickNum] ? G.pickNum : null, focusCls = (tab === 'formation' || tab === 'costumes') && num ? NUMBERS[num].cls : null;
      233→  for (const d of dancers) {
      234→    let p, act = 'wait', face = 0, k = '';
      235→    const first = numbersOf(d.cls)[0];
      236→    if (d.cls === focusCls && tab === 'formation') { const np = G.S.plan.numbers[num], F = G.editB && np.B ? np.B : np.A; p = stageToWorld(F[d.i].x, F[d.i].z); dress(d, num); d.wearing = num; k = 'f' + num; }
      237→    else if (d.cls === focusCls && tab === 'costumes') { p = spotPos(['podium'], d); dress(d, num); d.wearing = num; k = 'p' + num; }
      238→    else {
      239→      if (d.wearing !== first) { dress(d, first); d.wearing = first; }
      240→      if (d.cls === 'grandes' && !focusCls) { const F = G.S.plan.numbers.G1.A; p = stageToWorld(F[d.i].x, F[d.i].z); }
      241→      else if (d.cls === 'petits') { p = V(4.6 + (d.i % 3) * 1.4, 0, 1.2 + Math.floor(d.i / 3) * 1.4); act = 'warm'; face = PI / 4; }
      242→      else if (d.cls === 'ados') { p = V(9 + (d.i % 4) * 1.0, 0, 0.6 + Math.floor(d.i / 4) * 1.2); face = -0.5; }
      243→      else if (d.cls === 'mamans') { p = V(4.4 + d.i * 0.9, 0, 5.6); act = 'sit'; face = PI; }
      244→      else { const per = G.S.school.logeCols - 1; p = V(4.4 + (d.i % 5) * 1.5, 0, -6.6 + Math.floor(d.i / 5) * 2.4); face = 0.4; if (per < 5) p.x = 4; }
      245→    }
      246→    d.idle = p; d.idleAct = act; d.idleFace = face; d.idleKey = k; d.pos.copy(p); d.path = []; d.goalKey = ''; d.g.visible = true; d.emoji = null; d.bubble.visible = false; d.face = face;
      247→  }
