 83→// where dancer i of a number is, and what she is doing, at count c
 84→// np: the flat dance (perf.dance), played once through
 85→export function danceAt(numId, np, info, i, c, slips) {
 86→  const A = np.A, B = np.B || np.A, total = np.repeats * info.phrase;
 87→  if (!info.phrase) return { x: A[i].x, z: A[i].z, pose: REST, done: true };
 88→  const hurt = slips && slips.find((s) => s.i === i && s.kind === 'ankle' && info.starts[s.k] + 1 <= c);
 89→  if (hurt) { const at = danceAt(numId, np, info, i, info.starts[hurt.k] + 1, null); return { ...at, pose: { sit: 1, bow: 0.25, aL: 0.5, aR: 0.5, lR: 0.6 }, slip: hurt, jolt: false, done: c >= total }; }
 90→  const cc = Math.min(c, total - 1e-6), r = Math.floor(cc / info.phrase), pc = cc - r * info.phrase;
 91→  let k = 0; while (k + 1 < np.moves.length && info.starts[k + 1] <= pc) k++;
 92→  const m = MOVES[np.moves[k]], u = clamp((pc - info.starts[k]) / m.c, 0, 1);
 93→  const swapsBefore = r * info.swaps + np.moves.slice(0, k).filter((id) => MOVES[id].swap).length, F = swapsBefore % 2 ? B : A, Gf = F === A ? B : A;
