 95→  let x = F[i].x, z = F[i].z; if (m.swap && np.B) { x += (Gf[i].x - x) * u; z += (Gf[i].z - z) * u; }
 96→  const slip = slips && slips.find((s) => s.i === i && s.r === r && s.k === k);
 97→  // a step a grown-up added moves like the step it was given ("moves like", settings)
 98→  let pose = (MOVE_POSE[np.moves[k]] || MOVE_POSE[m.like] || (() => REST))(u);
 99→  if (slip && slip.kind === 'trip' && u > 0.3) pose = { sit: 1, bow: -0.35, aL: 1.6, aR: 1.6 };
100→  if (slip && slip.kind === 'forget') pose = { aR: 2.7, afR: 0.4, aL: 0.1, side: 0.1 };
101→  const link = k > 0 ? info.links[k - 1] : null;
102→  return { x: x + ox, z: z + oz, pose, slip, jolt: !!link && link.gap === 2 && u < 0.35, done: c >= total, k, r };
103→}
