105→/* ---------------- the run ---------------- */
106→let toastFn = () => {}, sayFn = () => '';
107→export function onSay(fn, toast) { sayFn = fn; toastFn = toast; }
108→export function startRun(mode, tryId) {
109→  if (mode === 'gala' && G.S.galaDone) return null;
110→  // a try-out rolls its own dice every time; the gala keeps the season's seed
111→  const res = simulate({ plan: G.S.plan, school: G.S.school, season: G.S.season, mode, seed: mode === 'try' ? (Math.random() * 1e9) >>> 0 : G.S.seed });
112→  const run = { mode, res, t: Math.min(RULES.arrive - 300, res.doors - 300), i: 0, done: false, feed: [], tryId, auto: '' };
113→  if (mode === 'try') {
114→    const it = res.order.items.find((x) => x.id === tryId); run.t = it.start - 4; run.endT = it.end + 3; run.item = it;
115→    run.i = res.trace.findIndex((e) => e.t >= run.t); if (run.i < 0) run.i = res.trace.length;
116→  } else run.endT = res.end;
117→  for (const d of dancers) { d.goalKey = ''; d.path = []; d.emoji = null; d.g.visible = false; d.bubble.visible = false; d.pos.set(0, 0, 30); }
118→  hideCars(); setParents(0);
119→  showTable(1, G.S.plan.bottles, G.S.plan.crepes);
120→  G.run = run; G.speed = 1;
121→  if (mode === 'try') cutTo('stage');
122→  return run;
123→}
124→function rateAt(t) {
125→  const run = G.run, R = run.res; if (run.mode === 'try') return (60 / NUMBERS[run.tryId].bpm) * RULES.countsPerSec;
126→  if (t < R.doors - 300) return 300; if (t >= R.finalEnd) return 50;
127→  const it = R.order.items.find((i) => t >= i.start && t < i.end); if (!it) return 90;
128→  if (it.kind === 'number') return (60 / NUMBERS[it.id].bpm) * RULES.countsPerSec;
129→  return it.kind === 'finale' ? 20 : it.kind === 'interval' ? 200 : 80;
130→}
131→export function stepRun(dt) {
132→  const run = G.run; if (!run || run.done) return;
133→  const R = run.res; run.t += dt * rateAt(run.t) * G.speed;
134→  while (run.i < R.trace.length && R.trace[run.i].t <= run.t) {
135→    const e = R.trace[run.i++]; if (!e.say) continue;
136→    if (run.mode === 'try' && !(e.who === `number:${run.tryId}`)) continue;
137→    const text = sayFn(e.say, R); run.feed.push({ t: e.t, text }); toastFn(text);
138→  }
139→  // the camera follows the numbers when she asked it to
140→  if (G.follow && run.mode !== 'try') {
141→    const it = R.order.items.find((i) => run.t >= i.start - 20 && run.t < i.end + 4), want = it && (it.kind === 'number' || it.kind === 'finale') ? 'stage' : 'school';
142→    if (want !== run.auto) { run.auto = want; if (view.mode !== want) { G.pickedRoom = null; cutTo(want); } }
143→  }
144→  if (run.t >= run.endT) { run.done = true; run.onDone && run.onDone(); }
145→}
146→export const currentItem = () => { const run = G.run; if (!run) return null; return run.res.order.items.find((i) => run.t >= i.start && run.t < i.end) || null; };
147→export function skipNumber() {
148→  const run = G.run; if (!run) return; const it = currentItem();
149→  const target = it && (it.kind === 'number' || it.kind === 'finale' || it.kind === 'interval') ? it.end : (run.res.order.items.find((i) => i.start > run.t) || { start: run.endT }).start;
150→  fastForward(Math.max(1, target - run.t + 0.5));
151→}
152→export function fastForward(sec) { const run = G.run; if (!run) return; const end = Math.min(run.endT, run.t + sec); while (G.run && !run.done && run.t < end) { const r = rateAt(run.t) * G.speed, step = Math.min(30, end - run.t); stepRun(step / r); } snapDancers(); }
