154→// a dancer's place and doing at day-time t
155→function segmentAt(d, t) {
156→  const s = G.run.res.seg[d.id]; if (!s) return null; let cur = null;
157→  for (const x of s) { if (x.t > t) break; if (x.spot) cur = { ...x, sleepy: cur && cur.sleepy }; else if (x.act === 'sleepy' && cur) cur = { ...cur, sleepy: x.until }; }
