160→const EMO = { arrive: '👋', warm: '🤸', hair: '💇', dress: '👗', change: '👗', wings: '✨', notready: '😕', bow: '😊', eat: '🍰', pout: '😕', party: '🎉', sleepy: '😴', leave: '👋' };
