172→      if (run.mode === 'try' && d.cls !== NUMBERS[run.tryId].cls) { d.g.visible = false; d.bubble.visible = false; continue; }
173→      if (!s || s.act === 'gone') { d.g.visible = false; d.bubble.visible = false; continue; }
174→      if (s.cos && s.cos !== d.wearing) { d.wearing = s.cos; dress(d, s.cos); }
