187→        if (!d.g.visible) { d.g.visible = true; d.pos.copy(target); }
188→        d.pos.copy(target); d.path = []; d.goalKey = 'dance';
189→      } else {
190→        target = spotPos(s.spot, d); key = s.spot.join('|');
191→        if (s.sleepy && run.t < s.sleepy && run.t >= RULES.bedtime && act !== 'bow') act = 'sleepy';
192→        if (!d.g.visible) { d.g.visible = true; d.pos.copy(target); d.path = []; d.goalKey = key; d.goal = target.clone(); }
193→        emo = EMO[act] || null;
194→        if ((act === 'wait' || act === 'wings') && s.spot[0] !== 'table') emo = needEmoji(d, run) || (act === 'wings' ? '✨' : null);
195→        if (act === 'wait' && s.spot[0] === 'dr') { const L = run.res.loge; if (d.idx >= L.seats && d.idx % 4 === 1) emo = '🪑'; }
196→      }
197→    } else {
