200→    }
201→    if (key !== 'dance' && (key !== d.goalKey || !d.goal || d.goal.distanceTo(target) > 0.01)) { d.goalKey = key; d.goal = target.clone(); d.path = route(d.pos, target); }
202→    let moving = false;
203→    if (key !== 'dance' && d.path.length) {
