220→    if (!moving && !pose && act !== 'bow') d.face = act === 'eat' || act === 'pout' || act === 'party' ? Math.atan2(TABLE.x - 1 - d.pos.x, TABLE.z - d.pos.z) : run ? d.face : d.idleFace;
221→    if (d.cls === 'petits' && !moving && !pose) u.body.rotation.z += S(performance.now() / 260 + d.i) * 0.05;
222→    d.g.position.set(d.pos.x, d.pos.y, d.pos.z); d.g.rotation.y = d.face;
