250→/* ---------------- the hall around the dancers: parents, cars, curtain, lights, the table ---------------- */
251→export function stepScene(dt) {
252→  const run = G.run;
253→  if (!run) { curtain.target = 1; stepLights(dt, false, false); return; }
254→  const R = run.res, t = run.t, it = currentItem(), dancing = it && (it.kind === 'number' || it.kind === 'finale');
255→  curtain.target = dancing || run.mode === 'try' ? 1 : 0;
256→  stepLights(dt, dancing, it && it.kind === 'number' && ['jazz', 'hiphop'].includes(NUMBERS[it.id].style));
257→  if (it && it.kind === 'number') setStageFloor(STYLES[NUMBERS[it.id].style].floor === 'bois' && R.rules.floors ? 'bois' : 'tapis');
258→  drawClock(t);
259→  // the parents: they take their seats as they arrive; the late ones come in during the first numbers
260→  const audience = R.parents.audience;
261→  let seated;
262→  if (R.parking) { const per = audience / Math.max(1, R.parking.cars); seated = R.parking.list.filter((c) => c.seated <= t).length * per; }
263→  else seated = clamp((t - R.doors) / Math.max(60, R.start - R.doors), 0, 1) * audience;
264→  if (run.mode === 'try') seated = audience;
265→  const gone = t > R.finalEnd + 120, clapping = R.order.items.some((x) => (x.kind === 'number' || x.kind === 'finale') && t >= x.end && t < x.end + 8);
266→  setParents(gone ? 0 : seated, clapping ? 1 : 0);
267→  // the cars
268→  if (R.parking) R.parking.list.forEach((c, k) => { const ahead = R.parking.list.filter((o) => o.k < k && o.arr <= t && o.through > t).length; placeCar(carMesh(k), c, t, ahead); });
269→  else for (let k = 0; k < Math.min(11, BAYS.length); k++) { const arr = R.doors + k * 60; placeCar(carMesh(k), { arr, through: arr, bay: k }, t, 0); }
270→  // the goûter table empties as the dancers eat
271→  const ate = R.trace.filter((e) => e.step === 'eat' && e.t <= t).length;
272→  let kcal = R.gouter.kcal0, cl = R.gouter.cl0;
273→  for (const e of R.gouter.eaters.slice(0, ate)) { kcal = Math.max(0, kcal - CLS[e.cls].kcal); cl = Math.max(0, cl - CLS[e.cls].juice); }
274→  showTable(kcal / Math.max(1, R.gouter.kcal0), cl / RULES.bottleCl, R.plan.crepes);
275→}
276→export function idleScene() {
277→  hideCars(); for (let k = 0; k < Math.min(4, BAYS.length); k++) placeCar(carMesh(k), { arr: 0, through: 0, bay: k }, 100, 0);
278→  setParents(0); curtain.target = 1; showTable(1, G.S.plan.bottles, G.S.plan.crepes); drawClock(G.S.plan.start);
279→}
