      582→/* ---------------- the verdicts ---------------- */
      583→export function sayText(say, R) {
      584→  const [k, ...a] = say, S = t().say, plan = R.plan;
      585→  switch (k) {
      586→    case 'wait': return S.wait(clsName(a[0]), durOf(a[1]));
      587→    case 'floorSwap': return S.floorSwap(durOf(a[0]), a[1]);
      588→    case 'startLate': return S.startLate(durOf(a[0]), clockOf(a[1]));
      589→    case 'yawn': return S.yawn(numName(a[0]));
      590→    case 'late': return S.late(durOf(a[0]));
      591→    case 'onTime': return S.onTime(clockOf(a[0]));
      592→    case 'collide': return S.collide(dancerName(a[0], a[1]), dancerName(a[0], a[2]));
      593→    case 'offstage': return S.offstage(dancerName(a[0], a[1]));
      594→    case 'hidden': return S.hidden(dancerName(a[0], a[1]), dancerName(a[0], a[2]));
      595→    case 'bump': return S.bump(dancerName(a[0], a[1]), dancerName(a[0], a[2]));
      596→    case 'jolt': return S.jolt(moveName(a[0]), moveName(a[1]));
      597→    case 'trip': return S.trip(dancerName(a[0], a[1]), moveName(a[2]));
      598→    case 'forget': return S.forget(dancerName(a[0], a[1]));
      599→    case 'ankle': return S.ankle(dancerName(a[0], a[1]), moveName(a[2]));
      600→    case 'musicLong': return S.musicLong(numName(a[0]), a[1]);
      601→    case 'musicShort': return S.musicShort(numName(a[0]), durOf(a[1]));
      602→    case 'applause': return S.applause(numName(a[0]), a[1]);
      603→    case 'cakeOut': return S.cakeOut(clsName(a[0]));
      604→    case 'juiceOut': return S.juiceOut(clsName(a[0]));
      605→    default: return S[k] ? S[k](...a) : k;
      606→  }
      607→}
      608→const L = (a, b = '', cls = '') => `<div class="${cls}"><span>${a}</span>${b !== '' ? `<span>${b}</span>` : ''}</div>`;
      609→const card = (title, ok, sayList, sum, badge = '') => `<div class="verdict${ok ? '' : ' fix'}"><div class="vt">${ok ? '🌟' : '🔧'} ${esc(title)} · ${esc(ok ? t().perfect : t().fix)}${badge ? ` <span class="badge">${badge}</span>` : ''}</div>${sayList.map((s) => `<p>${esc(s)}</p>`).join('')}${sum ? `<details><summary>${esc(t().why)}</summary><div class="sum">${sum}</div></details>` : ''}</div>`;
      610→export function verdictCards(R) {
      611→  const S = t().sum, P = R.plan, O = R.order, G2 = R.gouter, SY = t().say;
      612→  let out = '';
      613→  // the programme
      614→  let os = L(esc(S.start), esc(clockOf(P.start)));
      615→  os += L(esc(S.hair(O.hairTotal, R.loge.postes, O.hairMin)));
      616→  if (O.startLate) os += L(esc(S.realStart), esc(clockOf(O.start)), 'tot');
      617→  for (const it of O.items) {
      618→    if (it.co) os += L(`+ ${esc(durOf(it.co))} · ${esc(S.setChange)}`);
      619→    if (it.fl) os += L(`+ ${esc(durOf(it.fl))} · ${esc(S.floor(it.floor))}`);
      620→    if (it.change) { os += L(`<i>${esc(S.change(clsName(NUMBERS[it.id].cls), it.change.min))} ${it.change.lines.map(([k, m, o]) => esc(k === 'outfit' ? S.chLines.outfit(nm(OUTFITS[o]), m) : S.chLines[k](m))).join(' · ')}</i>`); }
      621→    if (it.wait) os += L(`+ ${esc(durOf(it.wait))} · ${esc(S.waitCos)}`);
      622→    os += L(`+ ${esc(durOf(it.dur))} · ${esc(itemName(it.id))}`, esc(clockOf(it.end)));
      623→  }
      624→  os += L(`${esc(S.end)} : ${esc(clockOf(O.end))} ${O.end <= RULES.hallCloses ? '≤' : '>'} ${esc(clockOf(RULES.hallCloses))}`, '', 'tot');
      625→  if (O.lastEnd.petits !== undefined) os += L(`${esc(S.petitsEnd)} ${esc(clockOf(O.lastEnd.petits))} ${O.lastEnd.petits <= RULES.bedtime ? '≤' : '>'} ${esc(clockOf(RULES.bedtime))}`, '', 'tot');
      626→  for (const y of O.yawns) os += L(esc(S.yawn(numName(y.id))));
      627→  const oSay = [O.late ? SY.late(durOf(O.late)) : SY.onTime(clockOf(O.end)), ...(O.startLate ? [SY.startLate(durOf(O.startLate))] : []), ...O.waits.map((w) => SY.wait(clsName(NUMBERS[w.id].cls), durOf(w.wait))), O.sleepy ? SY.sleepy() : '', ...O.yawns.slice(0, 1).map((y) => SY.yawn(numName(y.id)))].filter(Boolean);
      628→  out += card(t().vOrder, O.ok, oSay, os);
      629→  // each number
      630→  for (const it of O.items.filter((i) => i.kind === 'number')) {
      631→    const p = R.perf[it.id], N = NUMBERS[it.id], cls = CLS[N.cls], sp = p.spacing, m = p.music, np = P.numbers[it.id], nmOf = (i) => `${dancerName(N.cls, i)} (${i + 1})`, mm = (x) => `${num(x)} m`;
      632→    let s = L(`${esc(t().numParts.placement)} ${p.pts.placement}/3 · ${esc(t().numParts.music)} ${p.pts.music}/2 · ${esc(t().numParts.harmony)} ${p.pts.harmony}/3 · ${esc(t().numParts.execution)} ${p.pts.execution}/4 · ${esc(t().numParts.wow)} ${p.pts.wow}/5`, '', 'tot');
      633→    sp.collide.slice(0, 3).forEach((c) => (s += L(esc(S.span(nmOf(c.i), nmOf(c.j), mm(c.d), mm(cls.span))))));
      634→    sp.offstage.slice(0, 2).forEach((o) => (s += L(esc(Math.abs(o.x) > stageOf(G.S.school).halfW ? S.off(nmOf(o.i), num(Math.abs(o.x)), num(stageOf(G.S.school).halfW)) : S.offZ(nmOf(o.i))))));
      635→    if (sp.offstage.length && (p.info.net.dx || p.info.net.dz)) s += L(esc(S.drift(num(p.info.net.dx), num(p.info.net.dz))));
      636→    sp.hidden.slice(0, 2).forEach((h) => (s += L(esc(S.behind(nmOf(h.b), nmOf(h.f), mm(h.dx))))));
      637→    sp.bump.slice(0, 2).forEach((b) => (s += L(esc(S.bump(nmOf(b.i), nmOf(b.j))))));
      638→    if (sp.ok) s += L(esc(S.spanOk(mm(cls.span))));
      639→    s += L(esc(S.counts(durOf(m.dur), m.bpm, m.counts))) + L(esc(S.chainSum(chainSum(m.parts), m.have, m.counts)), '', 'tot');
      640→    p.info.links.filter((l) => l.gap === 2).forEach((l) => (s += L(esc(S.link(moveName(l.from), moveName(l.to))))));
      641→    p.info.links.filter((l) => l.off).slice(0, 2).forEach((l) => (s += L(esc(S.linkOff(moveName(l.to))))));
      642→    s += L(esc(S.harmony(p.pts.harmony)));
      643→    s += L(esc(S.state(p.state)));
      644→    for (const r of riskReasons(p, cls)) s += L(`· ${esc(r)}`);
      645→    s += L(esc(R.mode !== 'rehearsal' ? S.slips(p.slips.length) : S.expected(num(p.ex.expected, 1))), '', 'tot');
      646→    if (p.wow.src.length) s += L(`✨ ${p.wow.src.map((w) => esc(t().wow[w])).join(' · ')}`);
      647→    const sayL = [];
      648→    sp.collide.slice(0, 1).forEach((c) => sayL.push(SY.collide(dancerName(N.cls, c.i), dancerName(N.cls, c.j))));
      649→    sp.offstage.slice(0, 1).forEach((o) => sayL.push(SY.offstage(dancerName(N.cls, o.i))));
      650→    sp.hidden.slice(0, 1).forEach((h) => sayL.push(SY.hidden(dancerName(N.cls, h.b), dancerName(N.cls, h.f))));
      651→    sp.bump.slice(0, 1).forEach((b) => sayL.push(SY.bump(dancerName(N.cls, b.i), dancerName(N.cls, b.j))));
      652→    if (m.diff > 0) sayL.push(SY.musicLong(numName(it.id), m.stopsIn)); if (m.diff < 0) sayL.push(SY.musicShort(numName(it.id), durOf(m.playsOn)));
      653→    const jl = p.info.links.find((l) => l.gap === 2); if (jl) sayL.push(SY.jolt(moveName(jl.from), moveName(jl.to)));
      654→    if (R.mode !== 'rehearsal' && p.slips.length) sayL.push(S.slips(p.slips.length));
      655→    out += card(`${clsName(N.cls)} · ${numName(it.id)}`, sp.ok && m.ok && !jl, sayL, s, t().ptsOf(p.total, p.max));
      656→  }
      657→  // the goûter
      658→  let gs = R.rules.classes.map((c) => L(esc(S.kcal(c, CLS[c].n, CLS[c].kcal)), `${CLS[c].n * CLS[c].kcal} kcal`)).join('');
      659→  gs += L(esc(S.total(G2.needKcal)), '', 'tot');
      660→  const parts = [`${P.cakeG} g × 4 = ${G2.offer.cake} kcal`, ...(P.crepes ? [`${P.crepes} × 150 = ${G2.offer.crepes}`] : []), ...(P.compotes ? [`${P.compotes} × 70 = ${G2.offer.compotes}`] : [])].join(' + ');
      661→  gs += L(`${esc(S.offer(parts, G2.kcal0))} ${G2.kcal0 >= G2.needKcal ? '≥' : '<'} ${G2.needKcal}`, '', 'tot');
      662→  gs += R.rules.classes.map((c) => L(`${CLS[c].n} × ${CLS[c].juice} cl`, `${CLS[c].n * CLS[c].juice} cl`)).join('');
      663→  gs += L(esc(S.juice(G2.needCl, num(G2.needCl / 100, 2), P.bottles)), '', 'tot');
      664→  out += card(t().vGouter, G2.ok, [G2.cakeOut ? SY.cakeOut(clsName(G2.cakeOut)) : '', G2.juiceOut ? SY.juiceOut(clsName(G2.juiceOut)) : '', G2.ok ? SY.gouterOk() : ''].filter(Boolean), gs);
      665→  // the car park
      666→  if (R.parking) {
      667→    const pk = R.parking;
      668→    let ps = G.S.school.upgrades.covoit ? L(esc(S.carpool(pk.families, pk.famCars))) : '';
      669→    ps += L(esc(S.cars(pk.famCars, pk.guests, pk.cars))) + L(esc(S.bays(num(pk.width), pk.perRow, pk.rows, pk.bays))) + (pk.overflow ? L(esc(S.overflow(pk.overflow))) : '');
      670→    ps += L(esc(pk.lateCars ? S.lateCars(pk.lateCars, pk.lateParents) : S.noLate), '', 'tot');
      671→    out += card(t().vPark, pk.ok, [pk.lateCars ? SY.lateParents(pk.lateParents) : SY.parkOk()], ps);
      672→  }
      673→  // the parents
      674→  const ps = R.parents.sat.map(([k, v]) => L(esc(t().satLines[k]), `${v > 0 ? '+' : ''}${v}`)).join('') + L(`${R.parents.audience} / ${R.parents.seats}`, '', 'tot');
      675→  out += card(t().vParents, R.parents.satisfaction >= 70, [t().satisfaction(R.parents.satisfaction).replace(/<\/?b>/g, ''), ...quotes(R)], ps);
      676→  return out;
      677→}
      678→function quotes(R) {
      679→  const Q = t().quotes, keys = R.parents.sat.map(([k]) => k), out = [];
      680→  for (const k of ['late', 'lateParents', 'standing', 'yawns', 'startLate', 'buvetteShort', 'longWait', 'narrow']) if (keys.includes(k)) out.push(Q[k]);
      681→  if (R.order.sleepy) out.push(Q.sleepy);
      682→  if (keys.includes('comfy')) out.push(Q.comfy); if (keys.includes('buvette')) out.push(Q.buvette);
      683→  out.push(R.parents.satisfaction >= 80 ? Q.great : Q.good);
      684→  return out.slice(0, 3);
      685→}
      686→function paintResults() {
      687→  const run = G.run, R = run.res;
      688→  if (run.mode === 'try') {
      689→    sbody.innerHTML = `<h2>${esc(t().endTry)}</h2>` + tryCard(R, run.tryId) + trySteps(run, true);
      690→    goEl.innerHTML = `<button type="button" class="reh wide" id="backBtn">${esc(t().back)}</button>`;
      691→    goEl.querySelector('#backBtn').onclick = stopRun; hud(); return;
      692→  }
      693→  const head = run.mode === 'gala' ? `<p class="pts">${t().galaPts(R.points)}</p>` : `<p class="pts">${t().rehPts(R.points)}</p><p class="hint">${esc(t().rehNote)}</p>`;
      694→  sbody.innerHTML = `<h2>${esc(run.mode === 'gala' ? t().endGala : t().endReh)}</h2>${head}<div class="ptslist">${R.pts.map(([k, v]) => `<span>${esc(k.startsWith('num:') ? numName(k.slice(4)) : t().ptsLines[k])} <b>${v}</b></span>`).join('')}</div>${verdictCards(R)}`;
      695→  goEl.innerHTML = `<button type="button" class="reh wide" id="backBtn">${esc(t().back)}</button>` + (run.mode === 'gala' ? `<button type="button" class="gala wide" id="nextBtn">${esc(t().newSeason)}</button>` : '');
