699→}
700→// a try-out, step by step like a graph of nodes: each block of the dance, each step in it, and what happened on it
701→let lastNowStep = null;
702→function trySteps(run, all) {
703→  const R = run.res, id = run.tryId, P = R.perf[id], d = P.dance, info = P.info, N = NUMBERS[id], np = R.plan.numbers[id], it = run.item;
704→  const c = all ? Infinity : (run.t - it.start) * N.bpm / 60, S = t().step, who = (i) => esc(dancerName(N.cls, i));
705→  const byId = Object.fromEntries(np.blocks.map((b) => [b.id, b])), seen = P.slips.filter((x) => info.starts[x.k] < c);
706→  const count = (kind) => seen.filter((x) => x.kind === kind).length;
707→  let h = `<h3>${esc(S.head)}</h3><p class="stepsum">😵 ${count('trip')} · 🤔 ${count('forget')} · 🤕 ${count('ankle')}</p>`;
708→  const start = [...P.spacing.collide.map((x) => S.touch(who(x.i), who(x.j))), ...P.spacing.hidden.map((x) => S.hidden(who(x.b)))];
709→  if (start.length) h += `<div class="blk"><div class="bh">${esc(S.start)}</div><div class="step done bad"><span class="out">${start.slice(0, 6).join('<br>')}</span></div></div>`;
710→  h += '<div class="steps">';
711→  for (const mk of d.marks) {
712→    if (mk.k1 === mk.k0) continue;
713→    h += `<div class="blk" style="border-left-color:${blockColor(np, mk.block)}"><div class="bh">${esc(byId[mk.block].name)} <small>${mk.j + 1}</small></div>`;
714→    for (let k = mk.k0; k < mk.k1; k++) {
715→      const m = MOVES[d.moves[k]], s0 = info.starts[k], past = c >= s0 + m.c, now = !past && c >= s0;
716→      let out = '', bad = false;
717→      if (past || now) {
718→        const notes = [];
719→        if (s0 >= N.counts) notes.push(S.silent);
720→        for (const x of P.slips) if (x.k === k) notes.push(x.kind === 'trip' ? S.fell(who(x.i)) : x.kind === 'ankle' ? S.ankle(who(x.i)) : S.forgot(who(x.i)));
721→        if (k > 0 && info.links[k - 1].gap === 2) notes.push(S.jar);
722→        for (const o of P.spacing.offstage) if (o.k === k) notes.push(S.off(who(o.i)));
723→        for (const x of P.spacing.bump) if (x.k === k) notes.push(S.bump(who(x.i), who(x.j)));
724→        bad = notes.length > 0; out = bad ? notes.join('<br>') : past ? S.ok : '…';
725→      }
726→      h += `<div class="step${now ? ' now' : past ? ' done' : ''}${bad ? ' bad' : ''}" data-k="${k}"><span class="ic">${m.icon}</span><span class="mn">${esc(moveName(d.moves[k]))}</span><span class="out">${out}</span></div>`;
727→    }
728→    h += '</div>';
729→  }
730→  return h + '</div>';
731→}
732→function tryCard(R, id) {
733→  const html = verdictCards(R), box = document.createElement('div'); box.innerHTML = html;
734→  const want = `${clsName(NUMBERS[id].cls)} · ${numName(id)}`;
735→  const found = [...box.querySelectorAll('.verdict')].find((v) => v.querySelector('.vt').textContent.includes(want));
736→  return found ? found.outerHTML : '';
737→}
