739→/* ---------------- the seasons ---------------- */
740→export function nextSeason() {
741→  G.S.season++; G.S.galaDone = false; G.S.seed = (Math.random() * 1e9) >>> 0;
742→  addSeasonNumbers(G.S.plan, G.S.season); save();
