19→// stems: long enough to be rude wherever they appear, even spelt out "f u c k" or "s.h.i.t"
20→const STEMS = ['fuck', 'shit', 'cunt', 'bitch', 'whore', 'slut', 'asshole', 'arsehole', 'wanker', 'nigg', 'faggot', 'porn',
21→  'connard', 'connass', 'encule', 'salope', 'putain', 'enfoire', 'pouffias', 'batard', 'niquer', 'couille', 'branle', 'nichon',
22→  'merde', 'penis', 'vagin', 'bougnoul', 'hitler'];
23→
24→const LOOKALIKE = { 0: 'o', 1: 'i', 2: 'z', 3: 'e', 4: 'a', 5: 's', 6: 'g', 7: 't', 8: 'b', 9: 'g', '@': 'a', $: 's', '!': 'i', '|': 'i', '€': 'e', '£': 'l' };
25→// lower case, no accents, look-alike digits and signs turned back into letters
26→export function norm(s) {
27→  return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
28→    .replace(/œ/g, 'oe').replace(/æ/g, 'ae').replace(/ß/g, 'ss').replace(/[0-9@$!|€£]/g, (c) => LOOKALIKE[c]);
29→}
30→const once = (s) => s.replace(/(.)\1+/g, '$1');        // "fuuuck" → "fuck" (and "connard" → "conard")
31→const twice = (s) => s.replace(/(.)\1{2,}/g, '$1$1');  // "asss" → "ass", without turning "ass" into "as"
32→const WSET = new Set(WORDS), WONCE = new Set(WORDS.map(once).filter((w) => w.length >= 4));
33→const SONCE = STEMS.map(once);
34→
35→export function isRude(text) {
36→  const n = norm(text), words = n.split(/[^a-z]+/).filter(Boolean);
37→  for (const w of words) if (WSET.has(w) || WSET.has(twice(w)) || WONCE.has(once(w))) return true;
38→  // the letters alone, all run together: "f.u.c.k", "s h i t", "pu-tain"
39→  const run = words.join('');
40→  return STEMS.some((s) => run.includes(s)) || SONCE.some((s) => once(run).includes(s));
41→}
42→// web code or a link has no place in a name: it would never be run (esc() shows it as text) but it is refused all the same
43→export const isUnsafe = (text) => /[<>{}\\`]|https?:|www\.|:\/\/|\.(com|fr|net|org|io)\b|javascript:/i.test(String(text));
44→// control characters and the ones that flip text direction: invisible, and a way to hide a word
45→const strip = (s) => s.replace(/[\u0000-\u001f\u007f-\u009f​-‏‪-‮⁦-⁩﻿]/g, '').replace(/\s+/g, ' ').trim();
46→
47→// the text, tidied and cut to `max`, or `fallback` if it is empty, rude, or carries a link or code
48→export function clean(text, fallback = '', max = 40) {
49→  if (typeof text !== 'string') return fallback;
50→  const s = [...strip(text)].slice(0, max).join('').trim();
51→  if (!s || isRude(s) || isUnsafe(s)) return fallback;
52→  return s;
53→}

