        2→// step a grown-up has since removed. mend() repairs both without losing the rest of the plan.
        3→import test from 'node:test';
        4→import assert from 'node:assert/strict';
        5→import { mend, fresh } from '../src/state.js';
        6→import { simulate } from '../src/engine.js';
        7→
        8→// a save exactly as the game wrote it before change 001 (no `at`), from season 2
        9→function oldSave() {
       10→  const s = JSON.parse(JSON.stringify(fresh())); delete s.at;
       11→  s.season = 2; s.school.stars = 64; s.school.name = 'Les Étoiles';
       12→  s.plan.order = ['accueil', 'G1', 'M1', 'P1', 'entracte', 'P2', 'M2', 'G2', 'final'];
       13→  s.plan.numbers.G1.A[0] = { x: -4, z: 2 };
       14→  s.plan.numbers.G1.blocks.push({ id: 'b', name: 'Le final', moves: ['plie', 'tourne'] }); s.plan.numbers.G1.chain.push('b');
       15→  s.plan.snack = 'fruits'; s.plan.numbers.P1.costume.color = '#4f7cff';
       16→  return s;
       17→}
       18→
       19→test('18. An old save opens with its running order, formations, dances, costumes and snack untouched', () => {
       20→  const s = mend(oldSave());
