       30→  const s = oldSave();
       31→  s.plan.numbers.P1.costume.outfit = 'new3'; s.plan.numbers.P1.costume.shoes = 'gone'; s.plan.numbers.P1.costume.acc = 'gone';
       32→  s.plan.numbers.G1.blocks[0].moves.splice(1, 0, 'new2'); s.plan.hair.petits = 'gone';
