content:         1→// What every browser test needs: the game's own server on a free port with its own settings folder, a Chromium page at
        2→// the MacBook's size that records every console error, and the grown-ups' gate opened the way a grown-up does.
        3→// A developer tool only: the game never imports this (nor playwright).
        4→import { chromium } from 'playwright';
        5→import { spawn } from 'node:child_process';
        6→import { mkdtemp, mkdir } from 'node:fs/promises';
        7→import { tmpdir } from 'node:os';
        8→import { join, dirname } from 'node:path';
        9→import { fileURLToPath } from 'node:url';
       10→
       11→export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
       12→export const MAC = { width: 1426, height: 690 }, PHONE = { width: 390, height: 844 };
       13→export const SHOTS = process.env.SHOTS ? join(ROOT, 'changes', process.env.SHOTS) : null;
       14→
       15→// the server from `dir` (a copy of the folder, for the upgrade test), keeping its files in `data`
       16→export async function startServer({ dir = ROOT, data } = {}) {
       17→  data = data || await mkdtemp(join(tmpdir(), 'gala-data-'));
       18→  const proc = spawn(process.execPath, [join(dir, 'serve.mjs')], { cwd: dir, env: { ...process.env, PORT: '0', GALA_DIR: data }, stdio: ['ignore', 'pipe', 'inherit'] });
       19→  const port = await new Promise((res, rej) => {
       20→    let out = ''; proc.stdout.on('data', (b) => { out += b; const m = out.match(/localhost:(\d+)/); if (m) res(+m[1]); });
       21→    proc.on('exit', (c) => rej(new Error(`server exited ${c}`)));
       22→  });
       23→  return { url: `http://localhost:${port}/`, port, data, stop: () => new Promise((r) => { proc.once('exit', r); proc.kill(); }) };
       24→}
       25→export const launch = () => chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
       26→
       27→// a page that records errors; the web fonts are answered empty, so a test never depends on the internet
       28→export async function openGame(browser, url, { viewport = MAC, context = null } = {}) {
       29→  const ctx = context || await browser.newContext({ viewport, acceptDownloads: true });
       30→  const page = await ctx.newPage();
       31→  page.errors = [];
       32→  page.on('console', (m) => { if (m.type() === 'error') page.errors.push(m.text()); });
       33→  page.on('pageerror', (e) => page.errors.push(String(e)));
       34→  await page.route(/fonts\.(googleapis|gstatic)\.com/, (r) => r.fulfill({ status: 200, contentType: 'text/css', body: '' }));
       35→  await page.goto(url);
       36→  await ready(page);
       37→  return page;
       38→}
       39→export async function ready(page) {
       40→  await page.waitForFunction(() => window.__game && window.__game.frames > 3, null, { timeout: 30000 });
       41→  // the season's welcome card: closed, as a player would
       42→  const go = page.locator('#introGo'); if (await go.isVisible()) await go.click();
       43→}
       44→// hold ⚙️ for two seconds, then type the sum's answer
       45→export async function holdGear(page, ms = 2300) {
       46→  const box = await page.locator('#gearBtn').boundingBox();
       47→  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
       48→  await page.mouse.down(); await page.waitForTimeout(ms); await page.mouse.up();
       49→}
       50→export async function answerGate(page, right = true) {
       51→  const q = await page.locator('#gateQ').textContent(), [a, b] = q.match(/\d+/g).map(Number);
       52→  await page.fill('#gateIn', String(right ? a * b : a * b + 1)); await page.click('#gateOk');
       53→}
       54→export async function openSettings(page) {
       55→  await holdGear(page); await page.locator('#gateQ').waitFor(); await answerGate(page);
       56→  await page.locator('#grown .gpanel').waitFor();
       57→}
       58→export const tab = (page, k) => page.click(`[data-gtab="${k}"]`);
       59→// open a row of the settings (its fields show), by its table and id
       60→export async function row(page, table, id) {
       61→  const d = page.locator(`details[data-row="${table}|${id}"]`);
       62→  if ((await d.getAttribute('open')) === null) await d.locator('summary').click();
       63→  return d;
       64→}
       65→export const fieldIn = (page, table, id, f, kind = 'text') => page.locator(`#grown input[data-k="${kind}"][data-t="${table}"][data-id="${id}"][data-f="${f}"]`);
       66→export async function type(page, table, id, f, value, kind = 'text') { const el = fieldIn(page, table, id, f, kind); await el.fill(String(value)); await el.press('Enter'); }
       67→// close the screen: the game reloads with the settings applied
       68→export async function closeSettings(page) {
       69→  await Promise.all([page.waitForEvent('load'), page.click('#gClose')]);
       70→  await ready(page);
       71→}
       72→export const settingsFile = (page) => page.evaluate(() => JSON.parse(JSON.stringify(window.__game.settings.file)));
       73→export async function shot(page, name) { if (!SHOTS) return; await mkdir(SHOTS, { recursive: true }); await page.screenshot({ path: join(SHOTS, `${name}.png`) }); }
       74→// the toast's words, once it says something matching
       75→export async function toastSays(page, re) {
       76→  await page.waitForFunction((src) => new RegExp(src).test(document.querySelector('#toast').textContent), re.source, { timeout: 10000 });
       77→  return page.locator('#toast').textContent();
       78→}
