file_path: /private/var/tmp/own023-r3/A-vibe/work/gala/tests/browser/001-persistence.spec.mjs
content:         1→// Change 001, lines 10–12: the grown-ups' settings are theirs for good. After a reload, in a fresh browser, after the
        2→// browser's storage is cleared, after a new version of the game (a fresh copy of the folder, same settings folder), and on
        3→// another computer through "Save to a file" / "Load from a file".
        4→import test, { before, after } from 'node:test';
        5→import assert from 'node:assert/strict';
        6→import { cp, mkdtemp, readFile } from 'node:fs/promises';
        7→import { join } from 'node:path';
        8→import { tmpdir } from 'node:os';
        9→import { ROOT, startServer, launch, openGame, openSettings, tab, row, type, closeSettings, settingsFile, shot, toastSays } from './helpers.mjs';
       10→
       11→let browser; const servers = [];
       12→before(async () => { browser = await launch(); });
       13→after(async () => { await browser.close(); await Promise.all(servers.map((s) => s.stop())); });
       14→const start = async (opts) => {
       15→  if (!opts) for (const c of browser.contexts()) await c.close(); // a test's first server: the last test's pages are closed
       16→  const s = await startServer(opts); servers.push(s); return s; };
       17→const plieName = (page) => page.evaluate(() => { window.__game.setTab('formation'); return document.querySelector('#sbody .pal [data-add="plie"]').innerText; });
       18→
       19→test('10. When I clear the browser\'s data, or open the game in another browser, my settings are still there', async () => {
       20→  const s = await start();
       21→  const page = await openGame(browser, s.url);
       22→  await openSettings(page); await row(page, 'moves', 'plie'); await type(page, 'moves', 'plie', 'fr', 'Plié de reine');
       23→  await closeSettings(page);
       24→  assert.match(await plieName(page), /Plié de reine/, 'after a reload');
       25→  // the stored file sits outside the game folder
       26→  assert.deepEqual(JSON.parse(await readFile(join(s.data, 'settings.json'), 'utf8')).rows.moves.plie, { fr: 'Plié de reine' });
       27→  // this browser's storage cleared
       28→  await page.evaluate(() => { localStorage.clear(); sessionStorage.clear(); });
       29→  await page.reload(); await page.waitForFunction(() => window.__game && window.__game.frames > 3);
       30→  assert.match(await plieName(page), /Plié de reine/, 'after clearing localStorage');
