content:         1→// A child at the keyboard (change 001, line 16): a minute of random clicks, drags, typing and keys on every screen,
        2→// the grown-ups' settings included. It passes when the console stays clean, the school still draws, every number is a
        3→// sane number, and the save still opens. MONKEY_MS shortens it while developing.
        4→import test, { after } from 'node:test';
        5→import assert from 'node:assert/strict';
        6→import { startServer, launch, openGame, ready, openSettings, MAC, shot } from './helpers.mjs';
        7→
        8→const MS = +(process.env.MONKEY_MS || 60000);
        9→let browser, server;
       10→after(async () => { await browser?.close(); await server?.stop(); });
       11→
       12→// a seeded die, so a failure can be replayed (SEED=…)
       13→const SEED = +(process.env.SEED || Date.now() % 1e6);
       14→let a = SEED; const rnd = () => { a = (a + 0x6D2B79F5) >>> 0; let x = Math.imul(a ^ (a >>> 15), a | 1); x ^= x + Math.imul(x ^ (x >>> 7), x | 61); return ((x ^ (x >>> 14)) >>> 0) / 4294967296; };
       15→const pick = (list) => list[Math.floor(rnd() * list.length)];
       16→const WORDS = ['merde', 'Lou', '<b>x</b>', '-5', '99999', 'abc', '😀😀😀', 'www.x.com', '  ', '12', 'a'.repeat(80), 'NaN', '1e9', 'Plié'];
       17→// every screen in turn, the settings three times a round
       18→const SCREENS = ['settings', 'order', 'formation', 'settings', 'gouter', 'costumes', 'build', 'settings', 'shop', 'notebook', 'run'];
       19→const KEYS = ['Enter', 'Escape', 'Tab', 'ArrowLeft', 'ArrowUp', 'r', 'q', 'e', '+', '-', ' ', 'Backspace', 'a', '7'];
       20→
       21→test(`16. When a child clicks, drags, types and presses keys at random everywhere for a minute, nothing breaks (seed ${SEED})`, async () => {
       22→  browser = await launch(); server = await startServer();
       23→  const page = await openGame(browser, server.url);
       24→  page.on('dialog', (d) => (rnd() < 0.5 ? d.accept(pick(WORDS)) : d.dismiss()));
       25→  const end = Date.now() + MS; let n = 0, inSettings = 0;
       26→  while (Date.now() < end) {
       27→    n++;
       28→    try {
       29→      // now and then: a screen of its own (a tab, the settings, a run), so every screen gets its share
       30→      if (n % 15 === 1) {
       31→        const k = SCREENS[Math.floor(n / 15) % SCREENS.length];
       32→        if (k === 'settings') { if (!(await page.locator('#grown .gpanel').isVisible().catch(() => false))) { await openSettings(page); inSettings++; } await page.click(`[data-gtab="${pick(['moves', 'outfits', 'shop', 'school', 'file'])}"]`).catch(() => {}); }
       33→        else if (k === 'run') await page.evaluate(() => { if (!window.__game.G.run) window.__game.beginRun('rehearsal'); });
       34→        else await page.evaluate((t) => { if (!window.__game.G.run && !document.querySelector('#grown:not([hidden])')) window.__game.setTab(t); }, k);
       35→      }
       36→      const r = rnd();
       37→      if (r < 0.55) {
       38→        // a click on something that can be clicked, or anywhere
       39→        const els = await page.$$('button:visible, summary:visible, input:visible, select:visible, [data-dot]:visible, .card:visible');
       40→        const el = els.length && rnd() < 0.85 ? pick(els) : null;
       41→        if (el) await el.click({ timeout: 500, force: rnd() < 0.3 }); else await page.mouse.click(rnd() * MAC.width, rnd() * MAC.height);
       42→      } else if (r < 0.7) {
       43→        const x = rnd() * MAC.width, y = rnd() * MAC.height; await page.mouse.move(x, y); await page.mouse.down();
       44→        await page.mouse.move(x + (rnd() - 0.5) * 300, y + (rnd() - 0.5) * 300, { steps: 4 }); await page.mouse.up();
       45→      } else if (r < 0.85) {
       46→        const inputs = await page.$$('input[type="text"]:visible');
       47→        if (inputs.length) { const el = pick(inputs); await el.fill(pick(WORDS), { timeout: 500 }); await el.press(pick(['Enter', 'Tab'])); }
       48→      } else if (r < 0.95) await page.keyboard.press(pick(KEYS));
       49→      else await page.mouse.wheel(0, (rnd() - 0.5) * 600);
       50→      // a reload (closing the settings after a change does that) waits for the game to come back
       51→      if (!(await page.evaluate(() => !!window.__game).catch(() => false))) await ready(page);
       52→    } catch (e) {
       53→      if (!/Timeout|detached|not visible|not attached|Execution context|navigation|outside of the viewport|intercepts pointer/i.test(String(e))) throw e;
       54→      await page.waitForLoadState().catch(() => {});
       55→      if (!(await page.evaluate(() => !!window.__game).catch(() => false))) await ready(page);
       56→    }
       57→  }
       58→  await ready(page);
       59→  await shot(page, '16');
       60→  assert.deepEqual(page.errors, [], page.errors.join('\n'));
       61→  // still drawing
       62→  const f0 = await page.evaluate(() => window.__game.frames); await page.waitForTimeout(400);
       63→  assert.ok(await page.evaluate(() => window.__game.frames) > f0, 'the school still draws');
       64→  // every number sane
       65→  const S = await page.evaluate(() => window.__game.S);
       66→  for (const [k, v] of Object.entries({ stars: S.school.stars, cake: S.plan.cakeG, bottles: S.plan.bottles, start: S.plan.start, interval: S.plan.interval, season: S.season }))
       67→    assert.ok(Number.isFinite(v) && v >= 0 && v < 1e7, `${k} = ${v}`);
       68→  // and the save opens again, in this browser and in a new one
       69→  await page.evaluate(() => window.__game.settings.flush());
       70→  await page.reload(); await ready(page);
       71→  assert.equal(await page.evaluate(() => window.__game.S.v), 2);
       72→  const other = await openGame(browser, server.url);
       73→  assert.equal(await other.evaluate(() => window.__game.S.v), 2);
       74→  assert.deepEqual([...page.errors, ...other.errors], []);
       75→  console.log(`# ${n} random actions, the settings opened ${inSettings} times`);
       76→});
