 94→  const t0 = ctx.currentTime + 0.05, w = Math.max(0.15, Math.min(1, warmth)), n = Math.min(160, Math.round(secs * (12 + 30 * w)));
 95→  const bed = ctx.createBufferSource(); bed.buffer = noise; bed.loop = true; const bf = ctx.createBiquadFilter(); bf.type = 'bandpass'; bf.frequency.value = 2200; bf.Q.value = 0.4;
 96→  const bg = ctx.createGain(); bg.gain.setValueAtTime(0, t0); bg.gain.linearRampToValueAtTime(0.05 * w, t0 + 0.4); bg.gain.setValueAtTime(0.05 * w, t0 + secs * 0.6); bg.gain.linearRampToValueAtTime(0, t0 + secs);
 97→  bed.connect(bf); bf.connect(bg); bg.connect(master); bed.start(t0); bed.stop(t0 + secs + 0.1);
 98→  for (let i = 0; i < n; i++) {
 99→    const u = Math.random(), at = t0 + u * secs, fade = u < 0.7 ? 1 : 1 - (u - 0.7) / 0.3;
100→    burst(at, { freq: 1100 + Math.random() * 1600, q: 1.2, gain: (0.05 + Math.random() * 0.08) * w * fade, tau: 0.012 + Math.random() * 0.01, out: master });
101→  }
102→  stats.claps += n; stats.applause++;
103→}
104→
105→/* ---------------- following the run ---------------- */
106→function stopTune() {
107→  if (!cur) return; const bus = cur.bus; cur = null;
108→  if (ctx) { bus.gain.setTargetAtTime(0, ctx.currentTime, 0.04); setTimeout(() => bus.disconnect(), 500); }
109→}
110→const numberNow = (run) => run.res.order.items.find((it) => it.kind === 'number' && run.t >= it.start && run.t < it.end && (run.mode !== 'try' || it.id === run.tryId));
111→// once a frame, after the run has stepped
112→export function tick() {
113→  const run = G.run, live = !!(run && !run.done && soundOn() && ctx && ctx.state === 'running' && G.speed <= 2);
114→  const it = live ? numberNow(run) : null;
115→  if (cur && cur.it !== it) {
116→    const done = cur.lastC >= cur.sc.counts - 1, P = run && run.res.perf[cur.it.id];
117→    stopTune();
118→    if (done && live && run.mode === 'gala' && P) applause(P.total / P.max, 2.5 + 2.5 * (P.total / P.max));
119→  }
120→  if (live && run.mode === 'gala' && finaleRun !== run && run.t >= run.res.finalStart && run.t < run.res.finalEnd) { finaleRun = run; applause(0.4 + run.res.parents.satisfaction / 170, 7); }
121→  if (!it) return;
122→  const N = NUMBERS[it.id], c = (run.t - it.start) * N.bpm / 60, cps = RULES.countsPerSec * G.speed, now = ctx.currentTime;
123→  if (!cur) {
124→    const bus = ctx.createGain(); bus.connect(master);
125→    cur = { it, sc: score(it.id), bus, pans: {}, i: 0, upTo: Math.max(0, c - 0.6), lastC: c }; stats.tunes.push(it.id);
126→  }
127→  const ev = cur.sc.events;
128→  if (c < cur.lastC - 0.5 || c > cur.upTo + 2) { cur.i = 0; cur.upTo = c; } // a jump: carry on from here, no backlog
129→  while (cur.i < ev.length && ev[cur.i].c < cur.upTo - 1e-6) cur.i++;
130→  const horizon = c + cps * 0.15;
131→  while (cur.i < ev.length && ev[cur.i].c < horizon) {
132→    const e = ev[cur.i++], when = now + (e.c - c) / cps; if (when < now - 0.16) continue;
133→    const at = Math.max(now, when);
134→    if (e.drum) playDrum(e, at, cur.bus);
135→    else {
136→      const pan = e.pan || 0; let out = cur.pans[pan];
137→      if (!out) { out = cur.pans[pan] = ctx.createStereoPanner ? ctx.createStereoPanner() : ctx.createGain(); if (out.pan) out.pan.value = pan; out.connect(cur.bus); }
138→      playNote(e, at, e.d / cps, out);
139→    }
140→  }
141→  cur.upTo = horizon; cur.lastC = c;
142→}
143→export const musicState = () => ({ ctx: ctx ? ctx.state : 'none', on: soundOn(), playing: cur ? cur.it.id : null, ...stats, tunes: stats.tunes.slice() });
144→
145→// render `secs` seconds of a number's music from count `fromC`, offline, and measure it (the drive's ear: silent? clipping?)
146→export async function renderOffline(id, fromC = 0, secs = 6) {
147→  const keep = [ctx, master, noise], cps = RULES.countsPerSec, pans = {};
148→  build(new OfflineAudioContext(2, 44100 * secs, 44100));
149→  try {
150→    for (const e of score(id).events) {
151→      const at = (e.c - fromC) / cps; if (at < 0 || at >= secs) continue;
152→      if (e.drum) { playDrum(e, at, master); continue; }
153→      const pan = e.pan || 0; if (!pans[pan]) { pans[pan] = ctx.createStereoPanner(); pans[pan].pan.value = pan; pans[pan].connect(master); }
154→      playNote(e, at, e.d / cps, pans[pan]);
155→    }
156→    const buf = await ctx.startRendering(), L = buf.getChannelData(0); let peak = 0, sum = 0, quiet = 0;
157→    for (let i = 0; i < L.length; i++) { const a = Math.abs(L[i]); peak = Math.max(peak, a); sum += a * a; }
158→    for (let w = 0; w < secs * 4; w++) { let m = 0; for (let i = w * 11025; i < (w + 1) * 11025; i++) m = Math.max(m, Math.abs(L[i])); if (m < 0.01) quiet++; }
159→    return { id, fromC, peak: +peak.toFixed(3), rms: +Math.sqrt(sum / L.length).toFixed(3), silentQuarterSeconds: quiet };
160→  } finally { [ctx, master, noise] = keep; }
161→}

