100→const bubbleTex = new Map();
101→export function bubbleOf(emoji) {
102→  if (bubbleTex.has(emoji)) return bubbleTex.get(emoji);
103→  const cv = document.createElement('canvas'); cv.width = cv.height = 128; const g = cv.getContext('2d');
104→  g.fillStyle = 'rgba(255,255,255,.95)'; g.beginPath(); g.ellipse(64, 56, 54, 46, 0, 0, 7); g.fill(); g.beginPath(); g.arc(40, 108, 8, 0, 7); g.fill(); g.beginPath(); g.arc(30, 122, 4, 0, 7); g.fill();
105→  g.font = '58px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(emoji, 64, 60);
106→  const tx = new T.CanvasTexture(cv); tx.colorSpace = T.SRGBColorSpace; const m = new T.SpriteMaterial({ map: tx, transparent: true, depthWrite: false }); bubbleTex.set(emoji, m); return m;
