109→/* ---------------- poses ---------------- */
110→// p: { aL, aR (arms out to the side), afL, afR (arms forward), lL, lR (legs forward +, back −), y (rise, metres),
111→//      bow (lean forward), spin, sit (0 standing .. 1 on the floor), side (lean sideways), roll }
112→export const REST = { aL: 0.08, aR: 0.08, afL: 0, afR: 0, lL: 0, lR: 0, y: 0, bow: 0, spin: 0, sit: 0, side: 0, roll: 0 };
113→export function applyPose(d, p) {
114→  const u = d.g.userData, q = { ...REST, ...p };
115→  u.arms[0].rotation.set(-q.afL, 0, -q.aL); u.arms[1].rotation.set(-q.afR, 0, q.aR);
116→  u.legs[0].rotation.x = q.lL + q.sit * 1.45; u.legs[1].rotation.x = q.lR + q.sit * 1.45;
117→  u.body.rotation.set(q.bow, q.spin, q.side + q.roll);
118→  u.body.position.y = q.y / P_SCALE * 0.5 - q.sit * 0.92;
119→}

